window.LESSON_PAGES = {
  "1": {
    "title": "Bài 1: Tổng quan về mạng máy tính",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 01</p>\n        <h1>Tổng quan về mạng máy tính</h1>\n        <p>\n          Bài mở đầu giúp bạn hiểu mạng máy tính là gì, cách chúng hoạt động, vì sao Internet hình thành và các thành phần cốt lõi giúp mọi thiết bị trao đổi dữ liệu an toàn, nhanh chóng.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#components\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>20 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>4 phần</strong>\n            Khái niệm chủ đạo\n          </div>\n          <div class=\"stat\">\n            <strong>1960 → nay</strong>\n            Hành trình Internet\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu khái niệm mạng máy tính và lý do thế giới cần đến kết nối này.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Nhận diện các thành phần cơ bản tạo nên một mạng hoàn chỉnh.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Nắm các cột mốc lịch sử chính trong quá trình hình thành và phát triển.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Phân biệt mạng máy tính hiện đại với hệ thống độc lập, xây nền tảng cho bài học sau.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Vì sao chỉ với một chiếc laptop bạn có thể gửi email, xem video và họp online với người ở phía bên kia Trái đất?\"\n        </blockquote>\n        <p>Điều đó chỉ khả thi khi có mạng máy tính – xương sống của Internet và thế giới số.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Mạng máy tính là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p>Mạng máy tính là hệ thống gồm nhiều thiết bị (máy tính, máy chủ, smartphone, IoT...) được kết nối để trao đổi dữ liệu, chia sẻ tài nguyên và làm việc từ xa.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✨ Lợi ích</span>\n          <ul>\n            <li>Trao đổi dữ liệu theo thời gian thực.</li>\n            <li>Chia sẻ tài nguyên: file, máy in, Internet.</li>\n            <li>Hỗ trợ cộng tác, họp và xử lý từ xa.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧩 Ví dụ</span>\n          <ul>\n            <li>Mạng LAN trong văn phòng.</li>\n            <li>Mạng gia đình với router Wi-Fi.</li>\n            <li>Mạng Internet toàn cầu.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Cơ chế</p>\n      <h2>Nguyên lý hoạt động tổng quan</h2>\n      <p>Mọi phiên truyền thông tin đều đi qua chu trình chung \"thiết bị gửi → môi trường truyền → thiết bị nhận\". Dữ liệu được chia thành gói tin, gửi qua dây hoặc sóng và ghép lại để hiển thị chính xác.</p>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. Chuẩn bị</strong>\n          Thiết bị gửi đóng gói dữ liệu theo giao thức chung (ví dụ TCP/IP).\n        </div>\n        <div class=\"step\">\n          <strong>2. Vận chuyển</strong>\n          Các gói tin di chuyển qua môi trường truyền (cáp, quang, Wi-Fi, 4G/5G...).\n        </div>\n        <div class=\"step\">\n          <strong>3. Lắp ráp</strong>\n          Thiết bị nhận kiểm tra, ghép thứ tự và thông báo nếu có lỗi để truyền lại.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Lịch sử</p>\n      <h2>Từ máy tính độc lập đến \"Everything Connected\"</h2>\n      <p>Lịch sử mạng hình thành từ nhu cầu thực tế: chia sẻ tài nguyên, liên lạc từ xa và bảo vệ dữ liệu. Các giai đoạn chính gồm:</p>\n      <div class=\"timeline\">\n        <article class=\"timeline-card\">\n          <h3>1950–1960 · Máy tính độc lập</h3>\n          <ul>\n            <li>Máy tính cực đắt và cồng kềnh, mỗi hệ thống hoạt động riêng lẻ.</li>\n            <li>Người dùng phải đăng ký thời gian để sử dụng tài nguyên.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>1960–1980 · ARPANET & chia sẻ</h3>\n          <ul>\n            <li>Các phòng thí nghiệm của Mỹ kết nối để chia sẻ tài nguyên đắt đỏ.</li>\n            <li>Khái niệm gói tin và chuyển mạch ra đời, đặt nền móng cho Internet.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>1990–2010 · Internet bùng nổ</h3>\n          <ul>\n            <li>TCP/IP trở thành chuẩn chung, web và email phổ biến toàn cầu.</li>\n            <li>Wi-Fi, băng thông rộng giúp mọi cá nhân tiếp cận mạng.</li>\n          </ul>\n        </article>\n\n        <article class=\"timeline-card\">\n          <h3></h3>\n          <ul>\n          \n          </ul>\n        </article>\n\n        <article class=\"timeline-card\">\n          <h3>2010–nay · Đám mây & IoT</h3>\n          <ul>\n            <li>Cloud (AWS, Azure, GCP) biến hạ tầng mạng thành dịch vụ.</li>\n            <li>Smartphone và hàng tỷ thiết bị IoT kết nối mọi lúc mọi nơi.</li>\n            <p>  </p>\n\n          </ul>\n        </article>\n\n        <article class=\"timeline-card\">\n          <h3></h3>\n          <ul>\n          \n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section id=\"components\">\n      <p class=\"section-heading\">Trọng tâm</p>\n      <h2>4 nhóm thành phần của một mạng hoàn chỉnh</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>1. Thiết bị đầu cuối</h3>\n          <p>Nơi dữ liệu được tạo ra và sử dụng: PC, laptop, điện thoại, máy chủ, camera IP, thiết bị IoT...</p>\n          <ul>\n            <li>Gửi dữ liệu: email, file, video, yêu cầu web.</li>\n            <li>Nhận dữ liệu từ thiết bị khác để xử lý hoặc hiển thị.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>2. Thiết bị mạng</h3>\n          <p>Các thiết bị trung gian quyết định hiệu năng, độ ổn định và bảo mật.</p>\n          <ul>\n            <li>Switch: kết nối thiết bị trong LAN.</li>\n            <li>Router: nối các mạng với nhau.</li>\n            <li>Access Point, modem, firewall, repeater...</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>3. Môi trường truyền dẫn</h3>\n          <p>\"Con đường\" tín hiệu di chuyển, có dây lẫn không dây.</p>\n          <ul>\n            <li>Có dây: cáp xoắn đôi (phổ biến, rẻ), cáp quang (tốc độ cao), cáp đồng trục.</li>\n            <li>Không dây: Wi-Fi, Bluetooth, sóng di động 4G/5G.</li>\n          </ul>\n          <p>Cùng thiết bị nhưng môi trường khác sẽ cho chất lượng mạng khác nhau.</p>\n        </div>\n        <div class=\"component-card\">\n          <h3>4. Giao thức mạng</h3>\n          <p>Bộ quy tắc giúp thiết bị hiểu nhau: đóng gói dữ liệu, gửi/nhận, xác nhận và xử lý lỗi.</p>\n          <ul>\n            <li>TCP/IP – nền tảng Internet.</li>\n            <li>HTTP/HTTPS – truy cập web.</li>\n            <li>FTP, SMTP, DNS – truyền file, email, phân giải tên miền.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: mạng gia đình thông minh</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>📡 Router kết nối đường truyền của ISP, phát Wi-Fi cho laptop, điện thoại, TV.</p>\n          <p>🔁 Các thiết bị chia sẻ Internet, truy cập dịch vụ online và truyền dữ liệu nội bộ.</p>\n          <p>🛡️ Firewall tích hợp bảo vệ khỏi truy cập trái phép, trong khi giao thức WPA2 đảm bảo mã hóa.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>Mạng gia đình là mô hình thu nhỏ của mạng doanh nghiệp: có đầu cuối, thiết bị mạng, môi trường truyền và giao thức đồng nhất.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Quan sát mạng ở nhà hoặc nơi làm việc để củng cố kiến thức:</p>\n      <ol>\n        <li>Liệt kê các thiết bị đầu cuối và thiết bị mạng bạn đang dùng.</li>\n        <li>Xác định môi trường truyền (cáp, Wi-Fi, 4G...).</li>\n        <li>Mô tả lợi ích cụ thể mà mạng đó mang lại cho bạn/đội nhóm.</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Mẹo nhỏ:</strong>\n        <p>Chụp nhanh sơ đồ tay hoặc ghi chú lại để sử dụng cho bài học sau về mô hình OSI.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "2": {
    "title": "Bài 2: Phân loại mạng (LAN, WAN, MAN, PAN)",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 02</p>\n        <h1>Phân loại mạng (LAN, WAN, MAN, PAN)</h1>\n        <p>\n          Bài học giúp bạn phân biệt các loại mạng theo phạm vi hoạt động, hiểu mục đích sử dụng và áp dụng đúng loại mạng cho tình huống thực tế.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>PAN</strong>\n            Mạng cá nhân\n          </div>\n          <div class=\"stat\">\n            <strong>LAN</strong>\n            Mạng cục bộ\n          </div>\n          <div class=\"stat\">\n            <strong>WAN</strong>\n            Mạng diện rộng\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Phân biệt được các loại mạng: <strong>LAN, WAN, MAN, PAN</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Hiểu <strong>phạm vi hoạt động</strong> và <strong>mục đích sử dụng</strong> của từng loại mạng.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Áp dụng đúng loại mạng cho <strong>tình huống thực tế</strong> (nhà ở, văn phòng, doanh nghiệp, thành phố).</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Tránh nhầm lẫn giữa các khái niệm mạng phổ biến trong đời sống và công việc.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <p>Bạn sử dụng:</p>\n        <ul>\n          <li>Wi-Fi ở nhà để kết nối laptop và điện thoại.</li>\n          <li>Internet để gửi email cho người ở quốc gia khác.</li>\n          <li>Bluetooth để kết nối tai nghe không dây.</li>\n        </ul>\n        <blockquote>\n          Các kết nối này có phải cùng một loại mạng không? Nếu không, chúng khác nhau ở điểm nào?\n        </blockquote>\n        <p>Để trả lời, chúng ta cần hiểu cách <strong>phân loại mạng máy tính theo phạm vi hoạt động</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Nội dung</p>\n      <h2>Phân loại mạng theo phạm vi</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p>Là cách chia mạng máy tính dựa trên <strong>phạm vi địa lý và quy mô kết nối</strong>.</p>\n        </div>\n      </div>\n      <div style=\"margin-top: 1.5rem;\">\n        <table class=\"comparison-table\">\n          <thead>\n            <tr>\n              <th>Loại mạng</th>\n              <th>Tên đầy đủ</th>\n              <th>Phạm vi</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td>PAN</td>\n              <td>Personal Area Network</td>\n              <td>Cá nhân</td>\n            </tr>\n            <tr>\n              <td>LAN</td>\n              <td>Local Area Network</td>\n              <td>Cục bộ</td>\n            </tr>\n            <tr>\n              <td>MAN</td>\n              <td>Metropolitan Area Network</td>\n              <td>Thành phố</td>\n            </tr>\n            <tr>\n              <td>WAN</td>\n              <td>Wide Area Network</td>\n              <td>Toàn cầu</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Các loại mạng</p>\n      <h2>Tóm tắt theo từng loại</h2>\n      <div class=\"type-grid\">\n        <div class=\"type-card\">\n          <span class=\"badge\">a. PAN – Mạng cá nhân</span>\n          <ul>\n            <li>Kết nối các thiết bị <strong>xung quanh một người</strong>.</li>\n            <li>Thường dùng <strong>Bluetooth, NFC</strong>.</li>\n            <li>Khoảng cách: <strong>vài mét</strong>.</li>\n          </ul>\n          <p>📌 Ví dụ: Điện thoại ↔ Tai nghe Bluetooth.</p>\n        </div>\n        <div class=\"type-card\">\n          <span class=\"badge\">b. LAN – Mạng cục bộ</span>\n          <ul>\n            <li>Kết nối thiết bị trong <strong>nhà, văn phòng, lớp học</strong>.</li>\n            <li>Tốc độ cao, ổn định.</li>\n            <li>Dùng <strong>Ethernet, Wi-Fi</strong>.</li>\n          </ul>\n          <p>📌 Ví dụ: Máy tính, máy in trong công ty.</p>\n        </div>\n        <div class=\"type-card\">\n          <span class=\"badge\">c. MAN – Mạng đô thị</span>\n          <ul>\n            <li>Kết nối nhiều LAN trong <strong>một thành phố</strong>.</li>\n            <li>Thường do <strong>ISP hoặc tổ chức lớn</strong> quản lý.</li>\n          </ul>\n          <p>📌 Ví dụ: Mạng trường đại học nhiều cơ sở trong cùng thành phố.</p>\n        </div>\n        <div class=\"type-card\">\n          <span class=\"badge\">d. WAN – Mạng diện rộng</span>\n          <ul>\n            <li>Kết nối trên <strong>quy mô quốc gia hoặc toàn cầu</strong>.</li>\n            <li>Internet là <strong>WAN lớn nhất</strong>.</li>\n          </ul>\n          <p>📌 Ví dụ: Truy cập website đặt tại Mỹ từ Việt Nam.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các thông số kỹ thuật cần nhớ</h2>\n      <table class=\"comparison-table\">\n        <thead>\n          <tr>\n            <th>Tiêu chí</th>\n            <th>PAN</th>\n            <th>LAN</th>\n            <th>MAN</th>\n            <th>WAN</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Phạm vi</td>\n            <td>Cá nhân</td>\n            <td>Tòa nhà</td>\n            <td>Thành phố</td>\n            <td>Toàn cầu</td>\n          </tr>\n          <tr>\n            <td>Công nghệ</td>\n            <td>Bluetooth</td>\n            <td>Ethernet, Wi-Fi</td>\n            <td>Cáp quang</td>\n            <td>Internet, vệ tinh</td>\n          </tr>\n          <tr>\n            <td>Tốc độ</td>\n            <td>Thấp</td>\n            <td>Cao</td>\n            <td>Trung bình</td>\n            <td>Thấp hơn LAN</td>\n          </tr>\n          <tr>\n            <td>Chi phí</td>\n            <td>Rất thấp</td>\n            <td>Thấp</td>\n            <td>Cao</td>\n            <td>Rất cao</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: Mạng công ty đa địa điểm</h2>\n      <div class=\"case-study\">\n        <div>\n          <p><strong>Bài toán:</strong> Một công ty có:</p>\n          <ul>\n            <li>Văn phòng 1: Hà Nội.</li>\n            <li>Văn phòng 2: TP.HCM.</li>\n            <li>Nhân viên làm việc tại nhà.</li>\n          </ul>\n          <p><strong>Giải pháp mạng:</strong></p>\n          <ul>\n            <li>Trong mỗi văn phòng → <strong>LAN</strong>.</li>\n            <li>Kết nối giữa Hà Nội ↔ TP.HCM → <strong>WAN</strong>.</li>\n            <li>Nhân viên dùng tai nghe, chuột không dây → <strong>PAN</strong>.</li>\n          </ul>\n          <p>👉 Kết hợp nhiều loại mạng trong <strong>một hệ thống hoàn chỉnh</strong>.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Gợi ý:</strong>\n          <p>Khi thiết kế mạng, hãy bắt đầu từ phạm vi nhỏ nhất (PAN/LAN) rồi mở rộng ra MAN/WAN.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <h3>Tổng kết kiến thức</h3>\n      <ul>\n        <li>PAN → Cá nhân → Bluetooth.</li>\n        <li>LAN → Cục bộ → Nhà, văn phòng.</li>\n        <li>MAN → Thành phố → Tổ chức lớn.</li>\n        <li>WAN → Toàn cầu → Internet.</li>\n      </ul>\n      <p>👉 Phân loại mạng giúp <strong>thiết kế hệ thống hiệu quả và tiết kiệm chi phí</strong>.</p>\n      <div class=\"callout\">\n        <strong>Bài tập về nhà:</strong>\n        <p>Hãy mô tả hệ thống mạng tại nhà bạn hoặc nơi làm việc, trả lời:</p>\n        <ol>\n          <li>Có những loại mạng nào? (PAN/LAN/WAN?)</li>\n          <li>Thiết bị nào thuộc từng loại?</li>\n          <li>Nếu mở rộng quy mô, bạn sẽ cần thêm loại mạng nào?</li>\n        </ol>\n        <p>📌 Viết ngắn gọn 5–7 dòng.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "3": {
    "title": "Bài 3: Kiến trúc mạng Client-Server và Peer-to-Peer",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 03</p>\n        <h1>Kiến trúc mạng: Client-Server và Peer-to-Peer (P2P)</h1>\n        <p>\n          Bài học giúp bạn hiểu kiến trúc mạng, phân biệt Client-Server và P2P, và lựa chọn mô hình phù hợp cho từng bối cảnh.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>2 kiến trúc</strong>\n            Client-Server · P2P\n          </div>\n          <div class=\"stat\">\n            <strong>Quy mô</strong>\n            Nhỏ đến doanh nghiệp\n          </div>\n          <div class=\"stat\">\n            <strong>So sánh rõ</strong>\n            Bảo mật · mở rộng\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu rõ <strong>kiến trúc mạng là gì</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Phân biệt được <strong>Client-Server</strong> và <strong>Peer-to-Peer (P2P)</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Biết <strong>khi nào nên dùng Client-Server, khi nào nên dùng P2P</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Ứng dụng kiến trúc mạng phù hợp cho <strong>nhà ở, văn phòng, doanh nghiệp</strong>.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <ul>\n          <li>Khi bạn mở <strong>website</strong>, máy bạn gửi yêu cầu và nhận dữ liệu từ một máy khác.</li>\n          <li>Khi bạn <strong>chia sẻ file trực tiếp</strong> giữa hai máy trong cùng mạng.</li>\n          <li>Khi nhiều người cùng truy cập <strong>một hệ thống quản lý chung</strong>.</li>\n        </ul>\n        <blockquote>\n          Máy tính trong mạng có luôn luôn đóng vai trò giống nhau không? Hay có máy chuyên phục vụ, có máy chỉ sử dụng dịch vụ?\n        </blockquote>\n        <p>Đó chính là sự khác biệt giữa <strong>Client-Server</strong> và <strong>Peer-to-Peer</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Nội dung</p>\n      <h2>Kiến trúc mạng phổ biến</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Khái niệm</span>\n          <p><strong>Kiến trúc mạng</strong> là cách <strong>tổ chức vai trò và mối quan hệ</strong> giữa các máy tính trong hệ thống mạng.</p>\n          <p>Hai kiến trúc phổ biến nhất là <strong>Client-Server</strong> và <strong>Peer-to-Peer (P2P)</strong>.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Chi tiết</p>\n      <h2>So sánh hai kiến trúc</h2>\n      <div class=\"model-grid\">\n        <div class=\"model-card\">\n          <span class=\"badge\">🔹 Client-Server</span>\n          <p><strong>Định nghĩa:</strong></p>\n          <ul>\n            <li><strong>Server</strong>: Máy chủ cung cấp dịch vụ, dữ liệu.</li>\n            <li><strong>Client</strong>: Máy trạm gửi yêu cầu và sử dụng dịch vụ.</li>\n          </ul>\n          <p><strong>Nguyên lý:</strong></p>\n          <ol>\n            <li>Client gửi yêu cầu (request).</li>\n            <li>Server xử lý.</li>\n            <li>Server trả kết quả (response).</li>\n          </ol>\n          <p><strong>Ví dụ dịch vụ:</strong></p>\n          <ul>\n            <li>Web server.</li>\n            <li>Mail server.</li>\n            <li>Database server.</li>\n            <li>File server.</li>\n          </ul>\n        </div>\n        <div class=\"model-card\">\n          <span class=\"badge\">🔹 Peer-to-Peer (P2P)</span>\n          <p><strong>Định nghĩa:</strong></p>\n          <ul>\n            <li>Tất cả các máy <strong>bình đẳng</strong>.</li>\n            <li>Mỗi máy vừa là <strong>Client</strong>, vừa là <strong>Server</strong>.</li>\n          </ul>\n          <p><strong>Nguyên lý:</strong></p>\n          <ul>\n            <li>Máy này yêu cầu → máy khác cung cấp trực tiếp.</li>\n            <li>Không cần máy chủ trung tâm.</li>\n          </ul>\n          <p><strong>Ví dụ:</strong></p>\n          <ul>\n            <li>Chia sẻ file trong mạng LAN nhỏ.</li>\n            <li>BitTorrent.</li>\n            <li>Kết nối máy in trực tiếp.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các đặc điểm cần nhớ</h2>\n      <table class=\"comparison-table\">\n        <thead>\n          <tr>\n            <th>Tiêu chí</th>\n            <th>Client-Server</th>\n            <th>Peer-to-Peer</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Máy chủ trung tâm</td>\n            <td>Có</td>\n            <td>Không</td>\n          </tr>\n          <tr>\n            <td>Quản lý</td>\n            <td>Tập trung</td>\n            <td>Phân tán</td>\n          </tr>\n          <tr>\n            <td>Bảo mật</td>\n            <td>Cao</td>\n            <td>Thấp</td>\n          </tr>\n          <tr>\n            <td>Khả năng mở rộng</td>\n            <td>Rất tốt</td>\n            <td>Kém</td>\n          </tr>\n          <tr>\n            <td>Chi phí</td>\n            <td>Cao</td>\n            <td>Thấp</td>\n          </tr>\n          <tr>\n            <td>Phù hợp</td>\n            <td>Doanh nghiệp</td>\n            <td>Nhóm nhỏ</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study</h2>\n      <div class=\"case-study\">\n        <div>\n          <h3>🌐 Case 1: Quán Internet nhỏ (10 máy)</h3>\n          <ul>\n            <li>Nhu cầu: Chia sẻ game, file.</li>\n            <li>Không cần quản lý phức tạp.</li>\n          </ul>\n          <p>👉 <strong>Giải pháp:</strong> Peer-to-Peer.</p>\n          <p>✔ Dễ triển khai, ✔ Chi phí thấp.</p>\n        </div>\n        <div>\n          <h3>🌐 Case 2: Công ty 100 nhân viên</h3>\n          <ul>\n            <li>Server lưu file, quản lý nhân sự, email nội bộ.</li>\n            <li>Cần phân quyền, sao lưu dữ liệu.</li>\n          </ul>\n          <p>👉 <strong>Giải pháp:</strong> Client-Server.</p>\n          <p>✔ Bảo mật, ✔ Quản lý tập trung, ✔ Dễ mở rộng.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <h3>5.1. Tổng kết kiến thức</h3>\n      <ul>\n        <li><strong>Client-Server:</strong> Có máy chủ trung tâm, phù hợp hệ thống lớn, chuyên nghiệp.</li>\n        <li><strong>Peer-to-Peer:</strong> Không có máy chủ, phù hợp mạng nhỏ, đơn giản.</li>\n      </ul>\n      <p>👉 Lựa chọn kiến trúc đúng giúp hệ thống ổn định, tiết kiệm chi phí, dễ quản lý và mở rộng.</p>\n      <div class=\"callout\">\n        <strong>5.2. Bài tập về nhà:</strong>\n        <p>Hãy phân tích hệ thống mạng tại nhà hoặc nơi làm việc của bạn:</p>\n        <ol>\n          <li>Đang sử dụng kiến trúc nào? (Client-Server hay P2P)</li>\n          <li>Thiết bị nào đóng vai trò Server?</li>\n          <li>Nếu số người dùng tăng gấp đôi, bạn có cần đổi kiến trúc không? Vì sao?</li>\n        </ol>\n        <p>📌 Trình bày ngắn gọn 6–8 dòng.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "4": {
    "title": "Bài 4: Mô hình OSI",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 04</p>\n        <h1>Mô hình OSI</h1>\n        <p>\n          Bài học giúp bạn hiểu mô hình tham chiếu 7 tầng OSI, cách các thiết bị từ nhiều hãng giao tiếp với nhau, và vì sao phân tầng giúp chẩn đoán sự cố mạng nhanh, chính xác.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#layers\" class=\"primary\">Xem 7 tầng</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>7 tầng</strong>\n            Chuẩn OSI\n          </div>\n          <div class=\"stat\">\n            <strong>ISO</strong>\n            Tổ chức phát triển\n          </div>\n          <div class=\"stat\">\n            <strong>Troubleshooting</strong>\n            Phân vùng lỗi nhanh\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p><strong>Tiêu chuẩn hóa tư duy:</strong> Hiểu cách các hãng công nghệ khác nhau giao tiếp nhờ một quy chuẩn chung.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p><strong>Kỹ năng xử lý sự cố:</strong> Biết cách phân vùng lỗi theo tầng (tầng 1 phần cứng, tầng 3 định tuyến IP).</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p><strong>Nền tảng chuyên môn:</strong> Nắm thứ tự và chức năng 7 tầng để học CCNA, CompTIA Network+.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Hãy tưởng tượng bạn gửi một bức thư tay cho một người bạn ở nước ngoài. Để thư đến đích, bạn cần: viết thư (Dữ liệu), chọn ngôn ngữ chung (Định dạng), cho vào bì thư (Đóng gói), ghi địa chỉ (Địa chỉ hóa), và gửi qua bưu điện (Truyền dẫn).\"\n        </blockquote>\n        <p>Trong mạng máy tính, nếu không có một mô hình chung, máy tính Dell sẽ không thể “nói chuyện” được với MacBook. <strong>Mô hình OSI</strong> chính là “luật giao thông” toàn cầu để mọi thiết bị mạng đều hiểu nhau.</p>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Mô hình OSI là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p>Mô hình OSI (Open Systems Interconnection) là mô hình tham chiếu gồm <strong>7 tầng</strong>, do tổ chức ISO phát triển. Nó chia nhỏ quá trình truyền tin phức tạp thành 7 bước logic.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧭 Ý nghĩa</span>\n          <p>Giúp mọi thiết bị, hệ điều hành và hãng công nghệ có chung ngôn ngữ để trao đổi dữ liệu an toàn, nhất quán.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"layers\">\n      <p class=\"section-heading\">Cấu trúc</p>\n      <h2>Chức năng 7 tầng (từ trên xuống dưới)</h2>\n      <div class=\"layer-grid\">\n        <div class=\"layer-card\">\n          <span class=\"badge\">Tầng 7 · Application</span>\n          <p>Cung cấp giao diện giữa người dùng và mạng (HTTP, FTP, SMTP).</p>\n        </div>\n        <div class=\"layer-card\">\n          <span class=\"badge\">Tầng 6 · Presentation</span>\n          <p>Mã hóa, nén và định dạng dữ liệu (JPG, MP4, SSL/TLS).</p>\n        </div>\n        <div class=\"layer-card\">\n          <span class=\"badge\">Tầng 5 · Session</span>\n          <p>Thiết lập, quản lý và kết thúc các phiên hội thoại.</p>\n        </div>\n        <div class=\"layer-card\">\n          <span class=\"badge\">Tầng 4 · Transport</span>\n          <p>Đảm bảo truyền dữ liệu tin cậy, sửa lỗi và kiểm soát luồng (TCP, UDP).</p>\n        </div>\n        <div class=\"layer-card\">\n          <span class=\"badge\">Tầng 3 · Network</span>\n          <p>Xác định con đường đi tốt nhất cho dữ liệu dựa trên địa chỉ IP (thiết bị: Router).</p>\n        </div>\n        <div class=\"layer-card\">\n          <span class=\"badge\">Tầng 2 · Data Link</span>\n          <p>Truyền dữ liệu giữa các thiết bị kề nhau dựa trên địa chỉ MAC (thiết bị: Switch).</p>\n        </div>\n        <div class=\"layer-card\">\n          <span class=\"badge\">Tầng 1 · Physical</span>\n          <p>Chuyển dữ liệu thành tín hiệu điện, ánh sáng hoặc sóng (cáp mạng, hub).</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ghi nhớ</p>\n      <h2>Các thông số kỹ thuật cần nhớ</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">PDU</span>\n          <p>Mỗi tầng có một đơn vị dữ liệu riêng (Protocol Data Unit).</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Tầng 4</span>\n          <p>Segment.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Tầng 3</span>\n          <p>Packet.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Tầng 2</span>\n          <p>Frame.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Tầng 1</span>\n          <p>Bits.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Ví dụ minh hoạ: \"No Internet Connection\"</h2>\n      <div class=\"case-study\">\n        <div>\n          <p><strong>Kiểm tra tầng 1:</strong> Đèn xanh trên cổng mạng có sáng không? Dây cáp có bị đứt không?</p>\n          <p><strong>Kiểm tra tầng 2:</strong> Máy tính có nhận được địa chỉ MAC của Router không?</p>\n          <p><strong>Kiểm tra tầng 3:</strong> Máy tính đã được cấp địa chỉ IP đúng chưa? → Việc phân tầng giúp bạn tìm ra lỗi cực nhanh thay vì kiểm tra mò mẫm.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Gợi ý:</strong>\n          <p>Bạn có thể kiểm tra theo từng tầng để khoanh vùng sự cố trước khi thay đổi cấu hình lớn.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <ol>\n        <li><strong>Mẹo nhớ:</strong> Học thuộc câu thần chú (từ tầng 1 đến 7): <strong>\"Phải Đi Ngủ Trưa Sau Phiên Ăn\"</strong> (Physical, Data Link, Network, Transport, Session, Presentation, Application).</li>\n        <li><strong>Tra cứu:</strong> Hãy tìm xem địa chỉ MAC của máy tính bạn là gì bằng lệnh <code>getmac</code> trong CMD.</li>\n      </ol>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "5": {
    "title": "Bài 5: Mô hình TCP/IP – \"Ngôn ngữ\" của Internet",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.75); letter-spacing: 0.35em;\">Bài học 05</p>\n        <h1>Mô hình TCP/IP – \"Ngôn ngữ\" của Internet</h1>\n        <p>Bộ giao thức giúp mọi ứng dụng trên thế giới trò chuyện an toàn và chính xác. Bài học này kết nối kiến thức OSI với thực tế: từ IP, TCP/UDP, port đến cách phân tích lỗi theo tầng.</p>\n        <div class=\"hero-stats\">\n          <div class=\"stat\"><strong>4 tầng</strong>Kiến trúc tinh gọn</div>\n          <div class=\"stat\"><strong>15 câu</strong>Quiz kiểm tra nhanh</div>\n          <div class=\"stat\"><strong>2 lệnh</strong>Netstat &amp; Tracert thực hành</div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả bạn sẽ đạt được</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\"><span>🎯 Hiểu vận hành</span><p>Nắm lộ trình dữ liệu đi từ ứng dụng này sang ứng dụng khác trên Internet.</p></div>\n        <div class=\"goal\"><span>🎯 Chẩn đoán lỗi</span><p>Biết phân loại sự cố theo từng tầng (Ứng dụng vs Truy cập mạng, v.v.).</p></div>\n        <div class=\"goal\"><span>🎯 Nắm giao thức cốt lõi</span><p>Hiểu vai trò của IP, TCP, UDP, cổng (Port) trong giao tiếp mạng.</p></div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\"Tại sao khi gõ https://www.google.com trên một máy đang dùng Wi-Fi tại Việt Nam, dữ liệu lại tìm đúng máy chủ Google ở Mỹ và không nhầm lẫn với hàng tỷ người khác?\"</blockquote>\n        <p>Câu trả lời nằm ở bộ giao thức TCP/IP – hệ quy tắc giống như bưu điện quốc tế quy định cách ghi địa chỉ, đóng gói và chọn tuyến đường.</p>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Mô hình TCP/IP gồm 4 tầng</h2>\n      <p>TCP/IP (Transmission Control Protocol / Internet Protocol) là kiến trúc thực tế của Internet, tinh gọn hơn mô hình OSI. Bốn tầng làm việc với nhau từ ứng dụng đến môi trường truyền dẫn.</p>\n      <div class=\"layer-grid\">\n        <div class=\"layer-card\">\n          <span class=\"label\">Tầng 4</span>\n          <h3>Application (Ứng dụng)</h3>\n          <ul>\n            <li>Cung cấp giao diện cho người dùng và các dịch vụ mạng.</li>\n            <li>Giao thức: HTTP/HTTPS (Web), FTP (File), SMTP (Email), DNS (Tên miền).</li>\n          </ul>\n        </div>\n        <div class=\"layer-card\">\n          <span class=\"label\">Tầng 3</span>\n          <h3>Transport (Giao vận)</h3>\n          <ul>\n            <li>Quản lý truyền dữ liệu giữa hai thiết bị đầu cuối; định tuyến đến đúng ứng dụng thông qua số cổng.</li>\n            <li>Giao thức: TCP (tin cậy, kiểm tra lỗi) và UDP (nhanh, không kiểm tra lỗi).</li>\n          </ul>\n        </div>\n        <div class=\"layer-card\">\n          <span class=\"label\">Tầng 2</span>\n          <h3>Internet (Mạng)</h3>\n          <ul>\n            <li>Định tuyến gói tin, chọn con đường tối ưu dựa trên địa chỉ IP.</li>\n            <li>Giao thức: IP (IPv4/IPv6) và ICMP (lệnh ping).</li>\n          </ul>\n        </div>\n        <div class=\"layer-card\">\n          <span class=\"label\">Tầng 1</span>\n          <h3>Network Access (Truy cập mạng)</h3>\n          <ul>\n            <li>Chuyển dữ liệu thành tín hiệu vật lý qua cáp hoặc sóng.</li>\n            <li>Chuẩn: Ethernet, Wi-Fi, địa chỉ MAC.</li>\n          </ul>\n        </div>\n      </div>\n      <table class=\"data-table\">\n        <thead>\n          <tr>\n            <th>Tầng</th>\n            <th>Đơn vị dữ liệu (PDU)</th>\n            <th>Thông số định danh</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Application</td><td>Data (Dữ liệu)</td><td>Loại dịch vụ: HTTP, FTP…</td></tr>\n          <tr><td>Transport</td><td>Segment (Phân đoạn)</td><td>Số cổng (Port number)</td></tr>\n          <tr><td>Internet</td><td>Packet (Gói tin)</td><td>Địa chỉ IP nguồn/đích</td></tr>\n          <tr><td>Network Access</td><td>Frame (Khung)</td><td>Địa chỉ MAC</td></tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Hành trình của một tin nhắn chat</h2>\n      <div class=\"steps\">\n        <div class=\"step\"><strong>1. Tầng Ứng dụng</strong>Bạn gõ “Hello” trong ứng dụng chat – dữ liệu ban đầu.</div>\n        <div class=\"step\"><strong>2. Tầng Giao vận</strong>Thông điệp được chia thành segment, gán số cổng (ví dụ 443) cho ứng dụng.</div>\n        <div class=\"step\"><strong>3. Tầng Internet</strong>Thêm địa chỉ IP của bạn và người nhận để packet biết điểm đến.</div>\n        <div class=\"step\"><strong>4. Tầng Truy cập mạng</strong>Packet biến thành frame chứa địa chỉ MAC và được truyền qua cáp/Wi-Fi dưới dạng bit.</div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Ứng dụng kiến thức ngay</h2>\n      <ol class=\"practice-list\">\n        <li><strong>Kiểm tra Port:</strong> Mở CMD, gõ <code>netstat -an</code> để xem máy đang mở những cổng nào.</li>\n        <li><strong>Kiểm tra đường đi:</strong> Gõ <code>tracert google.com</code> để biết gói tin đi qua bao nhiêu router trước khi tới Google.</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Mẹo:</strong> Nhìn vào kết quả netstat để liên hệ với các tầng Ứng dụng/Giao vận; còn tracert thể hiện hoạt động của tầng Internet khi định tuyến.</div>\n      </div>\n    </section>\n\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "6": {
    "title": "Bài 6: So sánh chi tiết OSI và TCP/IP",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 06</p>\n        <h1>So sánh chi tiết OSI và TCP/IP</h1>\n        <p>\n          Bài học giúp bạn phân biệt rõ mô hình OSI và TCP/IP, hiểu lý do học OSI nhưng ứng dụng thực tế dựa trên TCP/IP, và biết cách ánh xạ giao thức vào đúng tầng.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#mapping\" class=\"primary\">Xem so sánh</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>OSI 7 tầng</strong>\n            Khung tham chiếu\n          </div>\n          <div class=\"stat\">\n            <strong>TCP/IP 4 tầng</strong>\n            Chuẩn thực tế\n          </div>\n          <div class=\"stat\">\n            <strong>Mapping</strong>\n            Ghép tầng rõ ràng\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p><strong>Phân biệt rạch ròi:</strong> Hiểu vì sao học OSI (7 tầng) nhưng thực tế dùng TCP/IP (4 tầng).</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p><strong>Ánh xạ giao thức:</strong> Đặt HTTP, TCP, IP đúng vị trí trong cả hai mô hình.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p><strong>Tư duy hệ thống:</strong> Hiểu được tính kế thừa và sự tinh gọn trong thiết kế mạng hiện đại.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Tại sao trong các giáo trình mạng máy tính, người ta dành rất nhiều thời gian nói về 7 tầng OSI, nhưng khi bạn cấu hình Router hay cài đặt phần mềm, bạn chỉ thấy các thông số liên quan đến TCP/IP?\"\n        </blockquote>\n        <p>Thực tế, OSI giống như một <strong>bản vẽ kiến trúc</strong> chi tiết giúp các kỹ sư hiểu sâu về nguyên lý, còn TCP/IP giống như <strong>ngôi nhà đã xây xong</strong> để mọi người vào ở. Hiểu được sự khác biệt này sẽ giúp bạn không bị rối khi nghiên cứu sâu về quản trị mạng.</p>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nền tảng</p>\n      <h2>Khái niệm &amp; nguồn gốc</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Mô hình OSI</span>\n          <p>Do tổ chức ISO phát triển, mang tính học thuật cao, dùng để định nghĩa tiêu chuẩn cho việc giao tiếp mạng.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🌐 Mô hình TCP/IP</span>\n          <p>Do Bộ Quốc phòng Mỹ (DoD) phát triển, ra đời trước cả OSI và trở thành \"ngôn ngữ\" thực tế của Internet nhờ tính thực dụng.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"mapping\">\n      <p class=\"section-heading\">So sánh</p>\n      <h2>So sánh cấu trúc (Mapping)</h2>\n      <div class=\"mapping-grid\">\n        <div class=\"mapping-card\">\n          <span class=\"badge\">Nhóm tầng ứng dụng</span>\n          <p>TCP/IP gộp 3 tầng cao nhất của OSI (Application, Presentation, Session) thành 1 tầng Application. Lý do: các chức năng này thường do bản thân ứng dụng phần mềm tự xử lý.</p>\n        </div>\n        <div class=\"mapping-card\">\n          <span class=\"badge\">Tầng giao vận</span>\n          <p>Giữ nguyên ở cả hai mô hình.</p>\n        </div>\n        <div class=\"mapping-card\">\n          <span class=\"badge\">Tầng mạng</span>\n          <p>OSI gọi là Network, TCP/IP gọi là Internet. Chức năng định tuyến và địa chỉ IP là như nhau.</p>\n        </div>\n        <div class=\"mapping-card\">\n          <span class=\"badge\">Nhóm tầng dưới</span>\n          <p>TCP/IP gộp tầng Data Link và Physical của OSI thành tầng Network Access. Lý do: phần cứng mạng (như Card mạng) thường đảm nhiệm cả việc tạo khung dữ liệu và truyền tín hiệu vật lý.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các thông số kỹ thuật cần nhớ</h2>\n      <table class=\"comparison-table\">\n        <thead>\n          <tr>\n            <th>Đặc điểm</th>\n            <th>Mô hình OSI</th>\n            <th>Mô hình TCP/IP</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Số tầng</td>\n            <td>7 tầng</td>\n            <td>4 tầng (hoặc 5 tầng theo giáo trình mới)</td>\n          </tr>\n          <tr>\n            <td>Tính chất</td>\n            <td>Tham chiếu / Lý thuyết</td>\n            <td>Thực dụng / Tiêu chuẩn thực tế</td>\n          </tr>\n          <tr>\n            <td>Giao thức</td>\n            <td>Phụ thuộc vào tiêu chuẩn tầng</td>\n            <td>Kết hợp chặt chẽ (Bộ giao thức TCP/IP)</td>\n          </tr>\n          <tr>\n            <td>Ưu điểm</td>\n            <td>Dễ dạy, dễ học, phân chia rõ ràng</td>\n            <td>Tinh gọn, ổn định, phổ biến toàn cầu</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Ví dụ minh hoạ</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>Khi một lập trình viên viết ứng dụng gửi tin nhắn:</p>\n          <ul>\n            <li>Trong <strong>mô hình OSI</strong>, lập trình viên phải lo về cách mã hóa dữ liệu (Tầng 6) và quản lý phiên (Tầng 5).</li>\n            <li>Trong <strong>mô hình TCP/IP</strong>, lập trình viên chỉ cần gọi các hàm ở tầng Application, các việc còn lại đã có bộ thư viện chuẩn của hệ điều hành lo liệu.</li>\n          </ul>\n        </div>\n        <div class=\"callout\">\n          <strong>Gợi ý:</strong>\n          <p>TCP/IP tinh gọn hơn, nhưng OSI giúp giải thích rõ các vai trò và hiện tượng trong quá trình truyền dữ liệu.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <ol>\n        <li>Vẽ một sơ đồ so sánh 2 mô hình lên giấy. Sau đó, hãy dùng bút màu khác để điền các giao thức: <strong>HTTP, TCP, IP, Ethernet</strong>.</li>\n        <li>Sử dụng công cụ <strong>Wireshark</strong> (nếu có điều kiện) để bắt một gói tin Web và quan sát xem nó được hiển thị theo cấu trúc của OSI hay TCP/IP.</li>\n      </ol>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "7": {
    "title": "Bài 7: Các loại phương tiện truyền dẫn",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 07</p>\n        <h1>Các loại phương tiện truyền dẫn</h1>\n        <p>\n          Bài học giúp bạn hiểu sự khác nhau giữa cáp đồng, cáp quang và sóng vô tuyến, biết cách chọn phương tiện phù hợp và xử lý các vấn đề vật lý phổ biến.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>3 loại chính</strong>\n            Cáp đồng, quang, sóng\n          </div>\n          <div class=\"stat\">\n            <strong>100 m</strong>\n            LAN cáp đồng\n          </div>\n          <div class=\"stat\">\n            <strong>Hàng chục km</strong>\n            Cáp quang\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p><strong>Lựa chọn đúng loại cáp:</strong> Biết khi nào nên dùng cáp đồng, khi nào bắt buộc phải dùng cáp quang để tiết kiệm chi phí và tối ưu tốc độ.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p><strong>Xử lý sự cố vật lý:</strong> Hiểu rõ đặc điểm của từng loại đường truyền để phán đoán lỗi (do nhiễu điện từ, đứt cáp hay vật cản sóng).</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p><strong>Thiết kế hạ tầng cơ bản:</strong> Biết cách đọc các thông số kỹ thuật trên dây cáp để giám sát thi công mạng văn phòng/gia đình.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Tại sao khi bạn chơi Game Online hoặc thực hiện cuộc gọi Video, đôi khi hình ảnh bị giật lag (delay) dù gói cước Internet của bạn rất cao? Tại sao dây mạng LAN trong nhà chỉ dài được tối đa 100m, trong khi cáp quang biển có thể truyền dữ liệu xuyên đại dương hàng ngàn km mà không mất tín hiệu?\"\n        </blockquote>\n        <p>Câu trả lời nằm ở <strong>Phương tiện truyền dẫn</strong> – \"con đường\" mà các bit dữ liệu thực sự di chuyển.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Nội dung</p>\n      <h2>Các loại phương tiện truyền dẫn</h2>\n      <div class=\"media-grid\">\n        <div class=\"media-card\">\n          <span class=\"badge\">3.1. Cáp đồng xoắn đôi (Twisted Pair)</span>\n          <ul>\n            <li><strong>Khái niệm:</strong> Là loại dây gồm các cặp dây đồng xoắn lại với nhau để giảm nhiễu điện từ. Đây là loại cáp phổ biến nhất trong mạng LAN.</li>\n            <li><strong>Nguyên lý:</strong> Truyền dữ liệu bằng <strong>xung điện</strong>.</li>\n            <li><strong>Phân loại:</strong> <strong>UTP</strong> không có lớp bọc kim loại (dùng trong nhà, giá rẻ). <strong>STP/FTP</strong> có lớp bọc kim loại chống nhiễu (dùng trong môi trường công nghiệp).</li>\n          </ul>\n        </div>\n        <div class=\"media-card\">\n          <span class=\"badge\">3.2. Cáp quang (Fiber Optic)</span>\n          <ul>\n            <li><strong>Khái niệm:</strong> Là sợi thủy tinh cực tinh khiết, mỏng như sợi tóc.</li>\n            <li><strong>Nguyên lý:</strong> Truyền dữ liệu bằng <strong>xung ánh sáng</strong> dựa trên hiện tượng phản xạ toàn phần.</li>\n            <li><strong>Ưu điểm tuyệt đối:</strong> Không bị nhiễu điện từ, tốc độ cực cao, khoảng cách truyền đi xa hàng chục km.</li>\n          </ul>\n        </div>\n        <div class=\"media-card\">\n          <span class=\"badge\">3.3. Sóng vô tuyến (Wireless/Wi-Fi)</span>\n          <ul>\n            <li><strong>Khái niệm:</strong> Truyền dữ liệu qua không gian mà không cần dây dẫn vật lý.</li>\n            <li><strong>Nguyên lý:</strong> Sử dụng <strong>sóng điện từ</strong> ở các tần số khác nhau (2.4GHz, 5GHz).</li>\n            <li><strong>Đặc điểm:</strong> Linh hoạt nhưng dễ bị nhiễu bởi vật cản (tường, kim loại) và các thiết bị điện tử khác.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các thông số kĩ thuật cần nhớ</h2>\n      <table class=\"comparison-table\">\n        <thead>\n          <tr>\n            <th>Loại phương tiện</th>\n            <th>Tốc độ phổ biến</th>\n            <th>Khoảng cách tối đa</th>\n            <th>Đặc điểm nổi bật</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Cáp Cat5e/Cat6</td>\n            <td>100 Mbps - 10 Gbps</td>\n            <td>100 mét</td>\n            <td>Dễ bấm đầu, giá rẻ, dễ nhiễu.</td>\n          </tr>\n          <tr>\n            <td>Cáp quang Single-mode</td>\n            <td>&gt; 100 Gbps</td>\n            <td>Hàng chục km</td>\n            <td>Truyền xa, dùng cho trục chính.</td>\n          </tr>\n          <tr>\n            <td>Wi-Fi (802.11ac/ax)</td>\n            <td>433 Mbps - 10 Gbps</td>\n            <td>30 - 50 mét</td>\n            <td>Tiện lợi, phụ thuộc vật cản.</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <ol>\n        <li>Kiểm tra trên thân dây cáp mạng đang cắm vào máy tính/Router của bạn xem nó ghi là <strong>Cat5e</strong> hay <strong>Cat6</strong>.</li>\n        <li>Mở cửa sổ CMD (Windows + R -&gt; gõ <code>cmd</code>), gõ lệnh <code>ping google.com -t</code>. Sau đó thử rút dây mạng và chuyển sang dùng Wi-Fi để xem chỉ số <code>time (ms)</code> thay đổi như thế nào.</li>\n      </ol>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "8": {
    "title": "Bài 8: Các thiết bị phần cứng mạng cơ bản",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 08</p>\n        <h1>Các thiết bị phần cứng mạng cơ bản</h1>\n        <p>\n          Bài học giúp bạn phân biệt Hub, Switch và Router, nắm nguyên lý hoạt động, đọc thông số kỹ thuật cơ bản và ứng dụng để xây dựng mạng LAN đơn giản.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>3 thiết bị</strong>\n            Hub · Switch · Router\n          </div>\n          <div class=\"stat\">\n            <strong>Layer 1-3</strong>\n            Vai trò khác nhau\n          </div>\n          <div class=\"stat\">\n            <strong>LAN thực tế</strong>\n            Ứng dụng rõ ràng\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Phân biệt rõ <strong>Hub, Switch và Router</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Hiểu <strong>nguyên lý hoạt động</strong> của từng thiết bị.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Biết <strong>khi nào nên dùng thiết bị nào</strong> trong thực tế.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Đọc và hiểu các <strong>thông số kỹ thuật cơ bản</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Ứng dụng kiến thức để <strong>xây dựng một mạng LAN đơn giản</strong>.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          “Khi bạn gõ https://www.google.com/search?q=google.com và nhấn Enter, chỉ trong vài giây kết quả đã xuất hiện. Vậy máy tính của bạn gửi dữ liệu đi bằng cách nào, và ai chịu trách nhiệm dẫn đường cho dữ liệu đó?”\n        </blockquote>\n        <p>Để trả lời, ta cần hiểu vai trò của <strong>Hub</strong> (truyền dữ liệu cơ bản), <strong>Switch</strong> (điều phối trong mạng nội bộ) và <strong>Router</strong> (kết nối ra Internet).</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Nội dung</p>\n      <h2>Ba thiết bị cốt lõi</h2>\n      <div class=\"device-grid\">\n        <article class=\"device-card\">\n          <span class=\"badge\">🔹 Hub</span>\n          <h3>📖 Khái niệm</h3>\n          <p><strong>Hub</strong> là thiết bị mạng đơn giản dùng để kết nối nhiều máy tính, <strong>gửi dữ liệu đến tất cả các cổng</strong> mà không phân biệt người nhận.</p>\n          <h3>⚙️ Nguyên lý hoạt động</h3>\n          <ul>\n            <li>Hoạt động ở <strong>Tầng 1 – Physical Layer (OSI)</strong>.</li>\n            <li>Khi một máy gửi dữ liệu, hub <strong>phát (broadcast)</strong> đến toàn bộ thiết bị còn lại.</li>\n            <li>Không có khả năng xử lý thông minh.</li>\n          </ul>\n          <h3>🧾 Thông số kỹ thuật cần nhớ</h3>\n          <ul>\n            <li>OSI Layer: <strong>Layer 1</strong>.</li>\n            <li>Cách truyền dữ liệu: Broadcast.</li>\n            <li>Collision Domain: Chung toàn mạng.</li>\n            <li>Tốc độ: 10 / 100 Mbps.</li>\n            <li>Bảo mật: ❌ Không có.</li>\n          </ul>\n        </article>\n\n        <article class=\"device-card\">\n          <span class=\"badge\">🔹 Switch</span>\n          <h3>📖 Khái niệm</h3>\n          <p><strong>Switch</strong> là thiết bị kết nối các máy trong mạng LAN và <strong>chỉ gửi dữ liệu đến đúng thiết bị cần nhận</strong>.</p>\n          <h3>⚙️ Nguyên lý hoạt động</h3>\n          <ul>\n            <li>Hoạt động ở <strong>Tầng 2 – Data Link Layer</strong>.</li>\n            <li>Dựa vào <strong>địa chỉ MAC</strong>.</li>\n            <li>Lưu thông tin trong <strong>bảng MAC Address Table</strong>.</li>\n          </ul>\n          <figure>\n            <img src=\"B%C3%A0i%208%20C%C3%A1c%20thi%E1%BA%BFt%20b%E1%BB%8B%20ph%E1%BA%A7n%20c%E1%BB%A9ng%20m%E1%BA%A1ng%20c%C6%A1%20b%E1%BA%A3n%20(Hub,%20Swi/Network-diagram-System-design.png\" alt=\"Sơ đồ hoạt động của switch\" />\n          </figure>\n          <h3>🧾 Thông số kỹ thuật cần nhớ</h3>\n          <ul>\n            <li>OSI Layer: <strong>Layer 2</strong>.</li>\n            <li>Truyền dữ liệu: Unicast.</li>\n            <li>Collision Domain: Riêng từng cổng.</li>\n            <li>Tốc độ: 100 Mbps / 1 Gbps / 10 Gbps.</li>\n            <li>Hỗ trợ: VLAN, Port Security.</li>\n          </ul>\n        </article>\n\n        <article class=\"device-card\">\n          <span class=\"badge\">🔹 Router</span>\n          <h3>📖 Khái niệm</h3>\n          <p><strong>Router</strong> là thiết bị dùng để <strong>kết nối các mạng khác nhau</strong>, đặc biệt là kết nối mạng nội bộ ra Internet.</p>\n          <h3>⚙️ Nguyên lý hoạt động</h3>\n          <ul>\n            <li>Hoạt động ở <strong>Tầng 3 – Network Layer</strong>.</li>\n            <li>Sử dụng <strong>địa chỉ IP</strong>.</li>\n            <li>Có bảng định tuyến (Routing Table).</li>\n            <li>Thực hiện: NAT, DHCP, Firewall.</li>\n          </ul>\n          <figure>\n            <img src=\"B%C3%A0i%208%20C%C3%A1c%20thi%E1%BA%BFt%20b%E1%BB%8B%20ph%E1%BA%A7n%20c%E1%BB%A9ng%20m%E1%BA%A1ng%20c%C6%A1%20b%E1%BA%A3n%20(Hub,%20Swi/Computer-and-networks-Wireless-router-home-area-network-diagram-1.png\" alt=\"Sơ đồ kết nối router\" />\n          </figure>\n          <h3>🧾 Thông số kỹ thuật cần nhớ</h3>\n          <ul>\n            <li>OSI Layer: <strong>Layer 3</strong>.</li>\n            <li>Chức năng: Routing, NAT, DHCP, Firewall.</li>\n            <li>Cổng kết nối: LAN / WAN.</li>\n            <li>Tốc độ phụ thuộc phần cứng &amp; ISP.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section id=\"comparison\">\n      <p class=\"section-heading\">So sánh</p>\n      <h2>Bảng so sánh nhanh</h2>\n      <table class=\"comparison-table\">\n        <thead>\n          <tr>\n            <th>Thiết bị</th>\n            <th>OSI Layer</th>\n            <th>Mức độ thông minh</th>\n            <th>Ứng dụng</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Hub</td>\n            <td>Layer 1</td>\n            <td>❌ Không</td>\n            <td>Lỗi thời</td>\n          </tr>\n          <tr>\n            <td>Switch</td>\n            <td>Layer 2</td>\n            <td>✅ Trung bình</td>\n            <td>Mạng LAN</td>\n          </tr>\n          <tr>\n            <td>Router</td>\n            <td>Layer 3</td>\n            <td>✅ Cao</td>\n            <td>Mạng Internet</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <p><strong>Yêu cầu:</strong> Thiết kế một mạng văn phòng nhỏ gồm:</p>\n      <ul>\n        <li>1 Router</li>\n        <li>1 Switch</li>\n        <li>5 máy tính</li>\n        <li>Kết nối Internet</li>\n      </ul>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "9": {
    "title": "Bài 9: Kỹ thuật mã hóa tín hiệu và truyền dữ liệu",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 09</p>\n        <h1>Kỹ thuật mã hóa tín hiệu và truyền dữ liệu</h1>\n        <p>\n          Bài học giúp bạn hiểu vì sao dữ liệu số cần được mã hóa trước khi truyền, phân biệt mã hóa tín hiệu và mã hóa dữ liệu, và nắm các kỹ thuật phổ biến.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>3 nhóm mã hóa</strong>\n            Số–số, số–tương tự, tương tự–tương tự\n          </div>\n          <div class=\"stat\">\n            <strong>Bit &amp; Baud</strong>\n            Thông số cốt lõi\n          </div>\n          <div class=\"stat\">\n            <strong>Wi-Fi Case</strong>\n            Ví dụ thực tế\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu <strong>vì sao dữ liệu số cần phải mã hóa trước khi truyền</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Phân biệt được <strong>mã hóa tín hiệu</strong> và <strong>mã hóa dữ liệu</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Nhận biết các <strong>kỹ thuật mã hóa tín hiệu phổ biến</strong> (NRZ, Manchester, AM/FM/PM...).</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Hiểu ảnh hưởng của mã hóa đến <strong>tốc độ, độ tin cậy và nhiễu</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Áp dụng kiến thức để <strong>giải thích quá trình truyền dữ liệu thực tế</strong>.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          “Khi bạn gửi một tin nhắn ‘Hello’ từ điện thoại, làm sao chữ H – e – l – l – o lại biến thành tín hiệu điện, truyền đi trên cáp hoặc sóng vô tuyến, rồi lại hiện đúng nội dung ở thiết bị nhận?”\n        </blockquote>\n        <p>👉 Máy tính <strong>không truyền chữ</strong>, mà truyền <strong>tín hiệu</strong>. 👉 Để truyền được, dữ liệu phải được <strong>mã hóa</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Nền tảng cốt lõi</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Mã hóa tín hiệu</span>\n          <p>Là quá trình <strong>chuyển dữ liệu số (0/1)</strong> thành <strong>tín hiệu vật lý</strong> (điện, ánh sáng, sóng vô tuyến) để truyền qua môi trường.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">📖 Truyền dữ liệu</span>\n          <p>Là quá trình <strong>gửi – nhận dữ liệu</strong> giữa các thiết bị thông qua dây đồng, cáp quang, hoặc sóng vô tuyến.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Luồng tổng quát:</strong>\n        <div class=\"flow\">Dữ liệu → Mã hóa → Tín hiệu → Truyền → Giải mã → Dữ liệu</div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Kỹ thuật</p>\n      <h2>Các nhóm mã hóa tín hiệu phổ biến</h2>\n      <div class=\"encoding-grid\">\n        <div class=\"encoding-card\">\n          <span class=\"badge\">🔸 Digital → Digital</span>\n          <ul>\n            <li><strong>NRZ</strong> (Non-Return to Zero).</li>\n            <li><strong>Manchester</strong>.</li>\n            <li><strong>Differential Manchester</strong>.</li>\n          </ul>\n        </div>\n        <div class=\"encoding-card\">\n          <span class=\"badge\">🔸 Digital → Analog</span>\n          <ul>\n            <li><strong>ASK</strong> – Amplitude Shift Keying.</li>\n            <li><strong>FSK</strong> – Frequency Shift Keying.</li>\n            <li><strong>PSK</strong> – Phase Shift Keying.</li>\n          </ul>\n        </div>\n        <div class=\"encoding-card\">\n          <span class=\"badge\">🔸 Analog → Analog</span>\n          <ul>\n            <li><strong>AM</strong> – Điều biên.</li>\n            <li><strong>FM</strong> – Điều tần.</li>\n            <li><strong>PM</strong> – Điều pha.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các thông số kỹ thuật cần nhớ</h2>\n      <table class=\"comparison-table\">\n        <thead>\n          <tr>\n            <th>Thông số</th>\n            <th>Ý nghĩa</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Bit rate</td>\n            <td>Số bit truyền trong 1 giây (bps)</td>\n          </tr>\n          <tr>\n            <td>Baud rate</td>\n            <td>Số tín hiệu / giây</td>\n          </tr>\n          <tr>\n            <td>Băng thông</td>\n            <td>Dải tần truyền</td>\n          </tr>\n          <tr>\n            <td>Nhiễu</td>\n            <td>Tín hiệu không mong muốn</td>\n          </tr>\n          <tr>\n            <td>SNR</td>\n            <td>Tỷ lệ tín hiệu / nhiễu</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: Truyền dữ liệu qua Wi-Fi</h2>\n      <div class=\"case-study\">\n        <div>\n          <ol>\n            <li>Dữ liệu số từ máy tính.</li>\n            <li>Mã hóa thành tín hiệu số.</li>\n            <li>Điều chế thành sóng vô tuyến (OFDM, QAM).</li>\n            <li>Truyền qua không khí.</li>\n            <li>Thiết bị nhận giải điều chế và giải mã.</li>\n          </ol>\n          <p>👉 Nếu mã hóa kém:</p>\n          <ul>\n            <li>Tốc độ chậm.</li>\n            <li>Dễ lỗi.</li>\n            <li>Mất dữ liệu.</li>\n          </ul>\n        </div>\n        <div class=\"callout\">\n          <strong>Ghi nhớ:</strong>\n          <p>Mã hóa tốt giúp tăng tốc độ, ổn định và khả năng chống nhiễu khi truyền dữ liệu.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <h3>🔎 Tổng kết nhanh</h3>\n      <ul>\n        <li>Dữ liệu <strong>luôn phải mã hóa trước khi truyền</strong>.</li>\n        <li>Mã hóa ảnh hưởng trực tiếp đến: tốc độ, độ ổn định, khả năng chống nhiễu.</li>\n        <li>Mỗi môi trường truyền dùng <strong>kỹ thuật mã hóa khác nhau</strong>.</li>\n      </ul>\n      <div class=\"callout\">\n        <strong>Phần B – Bài thực hành:</strong>\n        <p><strong>Yêu cầu:</strong> Mô tả quá trình truyền dữ liệu khi gửi 1 tin nhắn từ điện thoại qua Wi-Fi.</p>\n        <ol>\n          <li>Dữ liệu ban đầu là gì?</li>\n          <li>Được mã hóa thành tín hiệu nào?</li>\n          <li>Truyền qua môi trường gì?</li>\n          <li>Thiết bị nhận giải mã ra sao?</li>\n        </ol>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "10": {
    "title": "Bài 10: Các cấu trúc liên kết mạng (Topology)",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 10</p>\n        <h1>Các cấu trúc liên kết mạng (Topology)</h1>\n        <p>\n          Bài học giúp bạn hiểu khái niệm topology, phân biệt Star, Bus, Mesh, so sánh ưu – nhược điểm và chọn cấu trúc phù hợp với mạng thực tế.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>3 topology</strong>\n            Star · Bus · Mesh\n          </div>\n          <div class=\"stat\">\n            <strong>Ổn định &amp; mở rộng</strong>\n            So sánh rõ ràng\n          </div>\n          <div class=\"stat\">\n            <strong>Ứng dụng thực tế</strong>\n            LAN · Backbone · Mạng cũ\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu khái niệm <strong>cấu trúc liên kết mạng (Topology)</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Phân biệt được <strong>Star, Bus, Mesh</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>So sánh ưu – nhược điểm của từng topology.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Biết <strong>lựa chọn topology phù hợp</strong> với từng mô hình mạng thực tế.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Phân tích lỗi mạng dựa trên topology.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          “Tại sao khi một sợi cáp mạng bị đứt, có nơi chỉ 1 máy mất mạng, nhưng có nơi cả hệ thống bị sập?”\n        </blockquote>\n        <p>👉 Câu trả lời nằm ở <strong>cấu trúc liên kết mạng</strong>. 👉 Topology quyết định độ ổn định, khả năng mở rộng và mức độ ảnh hưởng khi xảy ra sự cố.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Nội dung</p>\n      <h2>Các cấu trúc liên kết mạng phổ biến</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Khái niệm</span>\n          <p><strong>Network Topology</strong> là cách bố trí và kết nối các thiết bị mạng (máy tính, switch, router...) trong một hệ thống mạng.</p>\n          <ul>\n            <li>Vật lý (Physical Topology).</li>\n            <li>Logic (Logical Topology).</li>\n          </ul>\n        </div>\n      </div>\n      <div class=\"topology-grid\" style=\"margin-top: 1.5rem;\">\n        <article class=\"topology-card\">\n          <span class=\"badge\">🔸 Topology hình sao (Star)</span>\n          <ul>\n            <li>Tất cả thiết bị kết nối về <strong>thiết bị trung tâm</strong> (Switch/Hub).</li>\n            <li>Mọi dữ liệu đều đi qua thiết bị trung tâm.</li>\n          </ul>\n          <figure>\n            <img src=\"B%C3%A0i%2010%20C%C3%A1c%20c%E1%BA%A5u%20tr%C3%BAc%20li%C3%AAn%20k%E1%BA%BFt%20m%E1%BA%A1ng%20(Topology%20Star,%20/The-star-network-topology.png\" alt=\"Sơ đồ topology hình sao\" />\n          </figure>\n          <p><strong>Đặc điểm:</strong></p>\n          <ul>\n            <li>Dễ quản lý.</li>\n            <li>Một máy lỗi → không ảnh hưởng máy khác.</li>\n            <li>Thiết bị trung tâm hỏng → toàn mạng dừng.</li>\n          </ul>\n        </article>\n\n        <article class=\"topology-card\">\n          <span class=\"badge\">🔸 Topology đường thẳng (Bus)</span>\n          <ul>\n            <li>Các thiết bị dùng chung <strong>một đường truyền chính</strong>.</li>\n            <li>Dữ liệu broadcast trên toàn bus.</li>\n          </ul>\n          <figure>\n            <img src=\"B%C3%A0i%2010%20C%C3%A1c%20c%E1%BA%A5u%20tr%C3%BAc%20li%C3%AAn%20k%E1%BA%BFt%20m%E1%BA%A1ng%20(Topology%20Star,%20/Bus_Topology.png\" alt=\"Sơ đồ topology đường thẳng\" />\n          </figure>\n          <p><strong>Đặc điểm:</strong></p>\n          <ul>\n            <li>Ít cáp, chi phí thấp.</li>\n            <li>Dễ xảy ra collision.</li>\n            <li>Đứt cáp → toàn mạng ngừng.</li>\n          </ul>\n        </article>\n\n        <article class=\"topology-card\">\n          <span class=\"badge\">🔸 Topology lưới (Mesh)</span>\n          <p>Mỗi thiết bị kết nối với <strong>nhiều hoặc tất cả thiết bị khác</strong>.</p>\n          <figure>\n            <img src=\"B%C3%A0i%2010%20C%C3%A1c%20c%E1%BA%A5u%20tr%C3%BAc%20li%C3%AAn%20k%E1%BA%BFt%20m%E1%BA%A1ng%20(Topology%20Star,%20/mesh-network-topology.png\" alt=\"Sơ đồ topology lưới\" />\n          </figure>\n          <p><strong>Đặc điểm:</strong></p>\n          <ul>\n            <li>Độ tin cậy rất cao.</li>\n            <li>Có nhiều đường dự phòng.</li>\n            <li>Chi phí cao, cấu hình phức tạp.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các yếu tố cần nhớ</h2>\n      <table class=\"comparison-table\">\n        <thead>\n          <tr>\n            <th>Yếu tố</th>\n            <th>Ý nghĩa</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Khả năng chịu lỗi</td>\n            <td>Mạng vẫn hoạt động khi có sự cố</td>\n          </tr>\n          <tr>\n            <td>Chi phí triển khai</td>\n            <td>Cáp, thiết bị</td>\n          </tr>\n          <tr>\n            <td>Khả năng mở rộng</td>\n            <td>Thêm thiết bị mới</td>\n          </tr>\n          <tr>\n            <td>Độ phức tạp</td>\n            <td>Quản lý, bảo trì</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: Văn phòng doanh nghiệp</h2>\n      <div class=\"case-study\">\n        <div>\n          <ul>\n            <li><strong>Mạng LAN văn phòng</strong> → Star topology.</li>\n            <li><strong>Mạng backbone ISP</strong> → Mesh topology.</li>\n            <li><strong>Mạng cũ (Ethernet 10Base2)</strong> → Bus topology.</li>\n          </ul>\n          <p>👉 Doanh nghiệp hiện đại <strong>ưu tiên Star + Mesh lai</strong>.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Gợi ý:</strong>\n          <p>Ưu tiên star cho dễ quản lý, bổ sung mesh ở các tuyến quan trọng để tăng độ tin cậy.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <table class=\"comparison-table\">\n        <thead>\n          <tr>\n            <th>Topology</th>\n            <th>Ưu điểm</th>\n            <th>Nhược điểm</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Star</td>\n            <td>Dễ quản lý, ổn định</td>\n            <td>Phụ thuộc trung tâm</td>\n          </tr>\n          <tr>\n            <td>Bus</td>\n            <td>Rẻ, đơn giản</td>\n            <td>Dễ lỗi toàn mạng</td>\n          </tr>\n          <tr>\n            <td>Mesh</td>\n            <td>Rất tin cậy</td>\n            <td>Tốn chi phí</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "11": {
    "title": "Bài 11: Giao thức Ethernet và địa chỉ MAC",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 11</p>\n        <h1>Giao thức Ethernet và địa chỉ MAC</h1>\n        <p>\n          Bài học giúp bạn hiểu Ethernet là gì, vai trò trong mạng LAN, cách MAC Address định danh thiết bị và phân biệt MAC với IP.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>Ethernet</strong>\n            Chuẩn LAN phổ biến\n          </div>\n          <div class=\"stat\">\n            <strong>MAC 48-bit</strong>\n            Địa chỉ vật lý\n          </div>\n          <div class=\"stat\">\n            <strong>Layer 1-2</strong>\n            Physical · Data Link\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu được <strong>Ethernet là gì</strong> và vai trò trong mạng LAN.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Giải thích được <strong>địa chỉ MAC là gì</strong>, dùng để làm gì.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Phân biệt <strong>MAC Address</strong> với <strong>IP Address</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Hiểu cách các thiết bị <strong>nhận diện và giao tiếp trong mạng LAN</strong>.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <ul>\n          <li>Khi bạn cắm dây mạng vào máy tính, mạng <strong>tự động hoạt động</strong>.</li>\n          <li>Khi bạn kết nối Wi-Fi, router <strong>biết chính xác thiết bị nào đang truy cập</strong>.</li>\n          <li>Trong cùng một mạng LAN, các máy <strong>không bị nhầm lẫn dữ liệu</strong>.</li>\n        </ul>\n        <blockquote>\n          Làm sao các thiết bị trong mạng nhận diện đúng nhau? Và <strong>Ethernet đóng vai trò gì</strong> trong việc truyền dữ liệu đó?\n        </blockquote>\n        <p>Câu trả lời nằm ở <strong>Ethernet</strong> và <strong>địa chỉ MAC</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Định nghĩa</p>\n      <h2>Ethernet và MAC Address</h2>\n      <div class=\"topic-grid\">\n        <div class=\"topic-card\">\n          <span class=\"badge\">a. Giao thức Ethernet</span>\n          <ul>\n            <li><strong>Ethernet</strong> là <strong>chuẩn công nghệ mạng LAN</strong> phổ biến nhất.</li>\n            <li>Quy định cách đóng gói dữ liệu, truyền dữ liệu và truy cập đường truyền.</li>\n            <li>Hoạt động chủ yếu ở <strong>Layer 1</strong> và <strong>Layer 2</strong> (OSI).</li>\n          </ul>\n        </div>\n        <div class=\"topic-card\">\n          <span class=\"badge\">b. Địa chỉ MAC</span>\n          <ul>\n            <li><strong>MAC Address</strong> là <strong>địa chỉ vật lý</strong> gắn cố định vào card mạng (NIC).</li>\n            <li>Mỗi thiết bị mạng có <strong>một MAC duy nhất</strong>.</li>\n            <li>Dùng để nhận diện thiết bị và chuyển frame đúng đích trong <strong>mạng LAN</strong>.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Cách Ethernet và MAC hoạt động</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">a. Ethernet</span>\n          <ol>\n            <li>Dữ liệu được <strong>đóng gói thành Frame Ethernet</strong>.</li>\n            <li>Frame chứa MAC nguồn và MAC đích.</li>\n            <li>Frame truyền qua dây mạng / Wi-Fi.</li>\n            <li>Switch đọc MAC đích để chuyển đúng cổng.</li>\n          </ol>\n          <p>📌 Ethernet đảm bảo truyền đúng dữ liệu, đúng thiết bị, đúng thứ tự.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">b. MAC Address</span>\n          <ul>\n            <li>Mỗi card mạng có một MAC duy nhất.</li>\n            <li>Switch tạo <strong>bảng MAC Address Table</strong>.</li>\n            <li>Khi frame đến: nếu biết MAC đích → chuyển đúng cổng; nếu chưa biết → broadcast.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các thông số kỹ thuật cần nhớ</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">a. Cấu trúc địa chỉ MAC</span>\n          <ul>\n            <li>Độ dài: <strong>48 bit (6 byte)</strong>.</li>\n            <li>Dạng hiển thị: <code>AA:BB:CC:DD:EE:FF</code>.</li>\n          </ul>\n          <table class=\"comparison-table\">\n            <thead>\n              <tr>\n                <th>Thành phần</th>\n                <th>Ý nghĩa</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>3 byte đầu</td>\n                <td>Nhà sản xuất (OUI)</td>\n              </tr>\n              <tr>\n                <td>3 byte sau</td>\n                <td>Số định danh thiết bị</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">b. Chuẩn Ethernet phổ biến</span>\n          <table class=\"comparison-table\">\n            <thead>\n              <tr>\n                <th>Chuẩn</th>\n                <th>Tốc độ</th>\n                <th>Môi trường</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>Ethernet</td>\n                <td>10 Mbps</td>\n                <td>Cáp đồng</td>\n              </tr>\n              <tr>\n                <td>Fast Ethernet</td>\n                <td>100 Mbps</td>\n                <td>Cáp đồng</td>\n              </tr>\n              <tr>\n                <td>Gigabit Ethernet</td>\n                <td>1 Gbps</td>\n                <td>Cáp đồng / quang</td>\n              </tr>\n              <tr>\n                <td>10G Ethernet</td>\n                <td>10 Gbps</td>\n                <td>Cáp quang</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: Mạng LAN văn phòng nhỏ</h2>\n      <div class=\"case-study\">\n        <div>\n          <ul>\n            <li>1 Router</li>\n            <li>1 Switch</li>\n            <li>5 máy tính</li>\n          </ul>\n          <p><strong>Quá trình:</strong></p>\n          <ol>\n            <li>Máy A gửi dữ liệu cho Máy B.</li>\n            <li>Switch kiểm tra MAC đích.</li>\n            <li>Switch chuyển frame đúng cổng của Máy B.</li>\n            <li>Các máy khác <strong>không nhận dữ liệu</strong>.</li>\n          </ol>\n          <p>👉 Nhờ <strong>Ethernet + MAC Address</strong>, mạng hoạt động chính xác, không lãng phí băng thông, không nhầm dữ liệu.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Gợi ý:</strong>\n          <p>Ethernet đảm nhiệm việc đóng gói và truyền, còn MAC đảm bảo đúng đích trong LAN.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <h3>5.1. Tổng kết kiến thức</h3>\n      <ul>\n        <li><strong>Ethernet</strong>: Chuẩn mạng LAN phổ biến nhất, hoạt động ở Layer 2.</li>\n        <li><strong>MAC Address</strong>: Địa chỉ vật lý, duy nhất, dùng trong LAN.</li>\n        <li>Switch hoạt động dựa trên <strong>MAC Address</strong>.</li>\n      </ul>\n      <p>👉 Ethernet + MAC là <strong>nền tảng của mọi mạng LAN hiện đại</strong>.</p>\n      <div class=\"callout\">\n        <strong>5.2. Bài tập về nhà:</strong>\n        <p>Trên máy tính của bạn, hãy:</p>\n        <ol>\n          <li>Kiểm tra địa chỉ MAC của card mạng.</li>\n          <li>Ghi lại MAC Address.</li>\n          <li>Trả lời: MAC có thay đổi khi đổi Wi-Fi không? MAC có giống IP không? Vì sao?</li>\n        </ol>\n        <p>📌 Gợi ý lệnh:</p>\n        <ul>\n          <li>Windows: <code>ipconfig /all</code></li>\n          <li>Linux / macOS: <code>ifconfig</code></li>\n        </ul>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "12": {
    "title": "Bài 12: Giao thức ARP - Cầu nối giữa IP và MAC",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 12</p>\n        <h1>Giao thức ARP - Cầu nối giữa IP và MAC</h1>\n        <p>\n          Bài học giúp bạn hiểu vì sao cần ARP, cách ARP hoạt động, và vai trò của ARP trong mạng LAN thực tế.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>ARP Request</strong>\n            Broadcast\n          </div>\n          <div class=\"stat\">\n            <strong>ARP Reply</strong>\n            Unicast\n          </div>\n          <div class=\"stat\">\n            <strong>ARP Table</strong>\n            Lưu tạm thời\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu rõ <strong>vì sao cần giao thức ARP</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Giải thích được <strong>ARP hoạt động như thế nào</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Phân biệt <strong>IP Address</strong> và <strong>MAC Address</strong> trong truyền dữ liệu.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Hiểu các khái niệm: <strong>ARP Request, ARP Reply, ARP Table</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Nhận biết vai trò của ARP trong <strong>mạng LAN thực tế</strong>.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <p>Giả sử:</p>\n        <ul>\n          <li>Máy A có IP: <code>192.168.1.10</code></li>\n          <li>Máy B có IP: <code>192.168.1.20</code></li>\n          <li>Hai máy cùng mạng LAN</li>\n        </ul>\n        <p>👉 Máy A muốn gửi dữ liệu cho Máy B.</p>\n        <ul>\n          <li>IP dùng cho <strong>định tuyến logic</strong>.</li>\n          <li>Ethernet cần <strong>MAC Address</strong> để gửi frame.</li>\n        </ul>\n        <blockquote>\n          Máy A lấy MAC của Máy B bằng cách nào, khi chỉ biết IP?\n        </blockquote>\n        <p>Câu trả lời chính là <strong>ARP</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Định nghĩa</p>\n      <h2>ARP và bảng ARP</h2>\n      <div class=\"topic-grid\">\n        <div class=\"topic-card\">\n          <span class=\"badge\">a. Giao thức ARP</span>\n          <ul>\n            <li><strong>ARP</strong> chuyển đổi IP Address → MAC Address.</li>\n            <li>Hoạt động trong <strong>mạng LAN</strong>.</li>\n            <li>Là cầu nối giữa <strong>Layer 3 (IP)</strong> và <strong>Layer 2 (MAC/Ethernet)</strong>.</li>\n          </ul>\n          <p>📌 Không có ARP → IP <strong>không thể truyền dữ liệu</strong> trên Ethernet.</p>\n        </div>\n        <div class=\"topic-card\">\n          <span class=\"badge\">b. ARP Table</span>\n          <ul>\n            <li>Lưu trữ IP Address và MAC Address tương ứng.</li>\n            <li>Được lưu <strong>tạm thời</strong> trong bộ nhớ thiết bị.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Quá trình ARP Request / ARP Reply</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">Các bước chính</span>\n          <p><strong>Bước 1:</strong> Kiểm tra ARP Table.</p>\n          <p><strong>Bước 2:</strong> ARP Request (Broadcast): hỏi “Ai có IP 192.168.1.20?”.</p>\n          <p><strong>Bước 3:</strong> ARP Reply (Unicast): Máy B trả MAC cho Máy A.</p>\n          <p><strong>Bước 4:</strong> Cập nhật ARP Table và dùng cho lần gửi tiếp theo.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Khi nào không cần ARP?</span>\n          <ul>\n            <li>ARP Table còn hiệu lực.</li>\n            <li>Dữ liệu gửi <strong>ngay lập tức</strong> không cần broadcast.</li>\n            <li>ARP Entry tự xóa sau một thời gian (timeout).</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các thông số kỹ thuật cần nhớ</h2>\n      <table class=\"comparison-table\">\n        <thead>\n          <tr>\n            <th>Tiêu chí</th>\n            <th>Giá trị</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Phạm vi hoạt động</td>\n            <td>Mạng LAN</td>\n          </tr>\n          <tr>\n            <td>Kiểu truyền</td>\n            <td>Broadcast + Unicast</td>\n          </tr>\n          <tr>\n            <td>OSI Layer</td>\n            <td>Giữa Layer 2 &amp; 3</td>\n          </tr>\n          <tr>\n            <td>Tốc độ</td>\n            <td>Rất nhanh</td>\n          </tr>\n          <tr>\n            <td>Lưu trữ</td>\n            <td>ARP Table (tạm thời)</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: Mạng LAN văn phòng</h2>\n      <div class=\"case-study\">\n        <div>\n          <ul>\n            <li>1 Switch</li>\n            <li>1 Router</li>\n            <li>10 máy tính</li>\n          </ul>\n          <p><strong>Tình huống:</strong> PC1 lần đầu ping PC2.</p>\n          <p><strong>Quá trình:</strong></p>\n          <ol>\n            <li>PC1 chưa biết MAC của PC2.</li>\n            <li>Gửi ARP Request (broadcast).</li>\n            <li>PC2 trả ARP Reply.</li>\n            <li>PC1 cập nhật ARP Table.</li>\n            <li>Ping thành công.</li>\n          </ol>\n          <p>👉 Nếu ARP bị lỗi: ping thất bại, LAN không giao tiếp được.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Gợi ý:</strong>\n          <p>ARP hoạt động nhanh và trong suốt để các thiết bị trong LAN luôn tìm đúng MAC đích.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <h3>5.1. Tổng kết kiến thức</h3>\n      <ul>\n        <li>IP dùng để <strong>xác định logic</strong>.</li>\n        <li>MAC dùng để <strong>truyền dữ liệu vật lý</strong>.</li>\n        <li><strong>ARP là cầu nối</strong> giữa IP và MAC.</li>\n        <li>ARP chỉ hoạt động trong <strong>LAN</strong>.</li>\n        <li>ARP Request = Broadcast, ARP Reply = Unicast.</li>\n      </ul>\n      <p>👉 ARP là <strong>giao thức nền tảng</strong>, cực kỳ quan trọng trong mạng máy tính.</p>\n      <div class=\"callout\">\n        <strong>5.2. Bài tập về nhà:</strong>\n        <p>Trên máy tính của bạn:</p>\n        <ol>\n          <li>Mở Command Prompt / Terminal.</li>\n          <li>Chạy lệnh <code>arp -a</code>.</li>\n          <li>Quan sát: có bao nhiêu IP? IP nào là router?</li>\n          <li>Ping một IP mới, chạy lại <code>arp -a</code>, so sánh thay đổi.</li>\n        </ol>\n        <p>📌 Trả lời ngắn gọn 5–7 dòng.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "13": {
    "title": "Bài 13: Tổng quan về giao thức IP (IPv4)",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 13</p>\n        <h1>Tổng quan về giao thức IP (IPv4)</h1>\n        <p>\n          Bài học giúp bạn hiểu IP là gì, cấu trúc IPv4, phân biệt IP và MAC, và nền tảng cho Subnet, Routing, NAT.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>IPv4</strong>\n            32-bit address\n          </div>\n          <div class=\"stat\">\n            <strong>Layer 3</strong>\n            Network Layer\n          </div>\n          <div class=\"stat\">\n            <strong>Private IP</strong>\n            Dải phổ biến\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu <strong>giao thức IP là gì</strong> và vai trò trong mạng.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Nhận biết cấu trúc <strong>địa chỉ IPv4</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Phân biệt <strong>IP và MAC</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Hiểu khái niệm <strong>Network</strong> và <strong>Host</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Chuẩn bị nền tảng cho <strong>Subnet, Routing, NAT</strong>.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <p>IP là giao thức định danh và định tuyến dữ liệu giữa các thiết bị trong mạng. IP hoạt động ở <strong>Layer 3</strong> và không đảm bảo thứ tự hay việc gói tin đến nơi.</p>\n        <p>📌 IP chỉ chịu trách nhiệm: gắn địa chỉ, chọn đường đi.</p>\n        <p><strong>IPv4</strong> là phiên bản phổ biến nhất, dùng địa chỉ 32-bit.</p>\n        <p>Ví dụ: <code>192.168.1.10</code></p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Nội dung</p>\n      <h2>Khái niệm và nguyên lý</h2>\n      <div class=\"topic-grid\">\n        <div class=\"topic-card\">\n          <span class=\"badge\">a. Giao thức IP</span>\n          <ul>\n            <li>Định danh và định tuyến dữ liệu giữa các thiết bị.</li>\n            <li>Hoạt động ở <strong>Layer 3</strong> (OSI).</li>\n            <li>Không đảm bảo thứ tự hoặc việc gói tin đến nơi.</li>\n          </ul>\n          <p>📌 IP chịu trách nhiệm: gắn địa chỉ, chọn đường đi.</p>\n        </div>\n        <div class=\"topic-card\">\n          <span class=\"badge\">b. IPv4</span>\n          <ul>\n            <li>Phiên bản IP phổ biến nhất hiện nay.</li>\n            <li>Sử dụng địa chỉ <strong>32-bit</strong>.</li>\n            <li>Dạng thập phân có dấu chấm.</li>\n          </ul>\n          <p>Ví dụ: <code>192.168.1.10</code></p>\n        </div>\n      </div>\n\n      <div class=\"card-grid\" style=\"margin-top: 1.5rem;\">\n        <div class=\"card\">\n          <span class=\"badge\">Nguyên lý truyền dữ liệu</span>\n          <ol>\n            <li>Dữ liệu chia thành <strong>IP Packet</strong>.</li>\n            <li>Packet chứa IP nguồn và IP đích.</li>\n            <li>Router đọc IP đích và chuyển tiếp.</li>\n            <li>Packet đến đúng mạng đích.</li>\n          </ol>\n          <p>📌 IP cho phép dữ liệu đi qua nhiều mạng khác nhau, không phụ thuộc phần cứng.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">IP và ARP phối hợp</span>\n          <ul>\n            <li>IP xác định <strong>thiết bị logic</strong>.</li>\n            <li>ARP chuyển <strong>IP → MAC</strong> trong LAN.</li>\n            <li>Ethernet dùng MAC để truyền frame.</li>\n          </ul>\n          <p>👉 IP <strong>không thể hoạt động một mình</strong>.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các thông số kỹ thuật cần nhớ</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">a. Cấu trúc IPv4</span>\n          <ul>\n            <li>Độ dài: <strong>32 bit</strong>.</li>\n            <li>Chia thành <strong>4 octet (8 bit)</strong>.</li>\n          </ul>\n          <table class=\"comparison-table\">\n            <thead>\n              <tr>\n                <th>Ví dụ</th>\n                <th>192</th>\n                <th>168</th>\n                <th>1</th>\n                <th>10</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>Bit</td>\n                <td>8</td>\n                <td>8</td>\n                <td>8</td>\n                <td>8</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">b. Network và Host</span>\n          <table class=\"comparison-table\">\n            <thead>\n              <tr>\n                <th>Thành phần</th>\n                <th>Ý nghĩa</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>Network ID</td>\n                <td>Xác định mạng</td>\n              </tr>\n              <tr>\n                <td>Host ID</td>\n                <td>Xác định thiết bị</td>\n              </tr>\n            </tbody>\n          </table>\n          <p>📌 Việc phân chia phụ thuộc vào <strong>Subnet Mask</strong>.</p>\n        </div>\n      </div>\n\n      <div class=\"card-grid\" style=\"margin-top: 1.5rem;\">\n        <div class=\"card\">\n          <span class=\"badge\">c. Các lớp IPv4 (Classful)</span>\n          <table class=\"comparison-table\">\n            <thead>\n              <tr>\n                <th>Lớp</th>\n                <th>Dải IP</th>\n                <th>Mục đích</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>A</td>\n                <td>1 – 126</td>\n                <td>Mạng rất lớn</td>\n              </tr>\n              <tr>\n                <td>B</td>\n                <td>128 – 191</td>\n                <td>Mạng vừa</td>\n              </tr>\n              <tr>\n                <td>C</td>\n                <td>192 – 223</td>\n                <td>Mạng nhỏ</td>\n              </tr>\n              <tr>\n                <td>D</td>\n                <td>224 – 239</td>\n                <td>Multicast</td>\n              </tr>\n              <tr>\n                <td>E</td>\n                <td>240 – 255</td>\n                <td>Dự trữ</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">d. IP Private phổ biến</span>\n          <table class=\"comparison-table\">\n            <thead>\n              <tr>\n                <th>Dải IP</th>\n                <th>Sử dụng</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>10.0.0.0/8</td>\n                <td>Doanh nghiệp</td>\n              </tr>\n              <tr>\n                <td>172.16.0.0/12</td>\n                <td>Nội bộ</td>\n              </tr>\n              <tr>\n                <td>192.168.0.0/16</td>\n                <td>Gia đình, văn phòng</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: Mạng gia đình</h2>\n      <div class=\"case-study\">\n        <div>\n          <ul>\n            <li>Router: <code>192.168.1.1</code></li>\n            <li>Laptop: <code>192.168.1.10</code></li>\n            <li>Điện thoại: <code>192.168.1.20</code></li>\n          </ul>\n          <p><strong>Phân tích:</strong></p>\n          <ul>\n            <li>Network: <code>192.168.1.0</code></li>\n            <li>Các thiết bị khác nhau ở <strong>Host ID</strong>.</li>\n            <li>Router dùng IP để quản lý mạng và định tuyến ra Internet.</li>\n          </ul>\n          <p>👉 IP giúp thiết bị nhận diện nhau và giao tiếp xuyên mạng.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Gợi ý:</strong>\n          <p>IP quyết định hướng đi, còn MAC quyết định đích trong LAN.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <h3>5.1. Tổng kết kiến thức</h3>\n      <ul>\n        <li>IP là <strong>giao thức nền tảng của Internet</strong>.</li>\n        <li>IPv4 dùng địa chỉ <strong>32-bit</strong>.</li>\n        <li>IP hoạt động ở <strong>Layer 3</strong>.</li>\n        <li>IP xác định ai gửi, ai nhận, gói tin đi đâu.</li>\n      </ul>\n      <p>👉 <strong>Không có IP → không có Internet.</strong></p>\n      <div class=\"callout\">\n        <strong>5.2. Bài tập về nhà:</strong>\n        <ol>\n          <li>Kiểm tra IP Address hiện tại.</li>\n          <li>Ghi lại IP, Subnet Mask, Default Gateway.</li>\n          <li>Xác định IP thuộc Private hay Public? Network ID là gì?</li>\n        </ol>\n        <p>📌 Gợi ý lệnh:</p>\n        <ul>\n          <li>Windows: <code>ipconfig</code></li>\n          <li>Linux / macOS: <code>ifconfig</code> hoặc <code>ip a</code></li>\n        </ul>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "14": {
    "title": "Bài 14: Cách chia Subnet Mask (Chia mạng con) đơn giản nhất",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 14</p>\n        <h1>Cách chia Subnet Mask (Chia mạng con) đơn giản nhất</h1>\n        <p>\n          Bài học giúp bạn hiểu vì sao cần chia subnet, cách tính nhanh, và áp dụng vào tình huống thực tế để tối ưu IP.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Xem nội dung</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>Subnet</strong>\n            Mượn bit host\n          </div>\n          <div class=\"stat\">\n            <strong>Host</strong>\n            2^n − 2\n          </div>\n          <div class=\"stat\">\n            <strong>Bước nhảy</strong>\n            256 − Mask\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu <strong>vì sao cần chia subnet</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Biết <strong>Subnet Mask là gì</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Chia được mạng con theo <strong>số host hoặc số subnet</strong>.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Xác định Network ID, Broadcast, dải IP sử dụng.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Áp dụng chia subnet cho <strong>mạng thực tế</strong>.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <p>Bạn có mạng <code>192.168.1.0/24</code> với 200 thiết bị, sau này cần tách phòng ban:</p>\n        <ul>\n          <li>Phòng Kế toán: 30 máy</li>\n          <li>Phòng Kỹ thuật: 50 máy</li>\n          <li>Phòng Server: 10 máy</li>\n        </ul>\n        <blockquote>\n          Làm sao chia mạng để mỗi phòng độc lập, không lãng phí IP, dễ quản lý và bảo mật?\n        </blockquote>\n        <p>Câu trả lời là <strong>chia Subnet (mạng con)</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Nội dung</p>\n      <h2>Subnet Mask và nguyên lý chia subnet</h2>\n      <div class=\"topic-grid\">\n        <div class=\"topic-card\">\n          <span class=\"badge\">a. Subnet Mask là gì?</span>\n          <ul>\n            <li>Phân chia IP thành phần Network và Host.</li>\n            <li>Giúp router biết thiết bị thuộc mạng nào.</li>\n          </ul>\n          <p>Ví dụ:</p>\n          <ul>\n            <li>IP: <code>192.168.1.10</code></li>\n            <li>Mask: <code>255.255.255.0</code></li>\n            <li>CIDR: <code>/24</code></li>\n          </ul>\n        </div>\n        <div class=\"topic-card\">\n          <span class=\"badge\">b. Vì sao phải chia subnet?</span>\n          <ul>\n            <li>Giảm broadcast</li>\n            <li>Tăng bảo mật</li>\n            <li>Quản lý mạng hiệu quả</li>\n            <li>Tối ưu tài nguyên IP</li>\n          </ul>\n        </div>\n      </div>\n\n      <div class=\"card-grid\" style=\"margin-top: 1.5rem;\">\n        <div class=\"card\">\n          <span class=\"badge\">Ý tưởng cốt lõi</span>\n          <blockquote>Mượn bit từ phần Host → tạo thêm Network</blockquote>\n          <ul>\n            <li>Mỗi subnet có Network Address và Broadcast Address.</li>\n            <li>Số IP sử dụng được: <code>2^host − 2</code>.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Công thức nhanh</span>\n          <ul>\n            <li><strong>Số host tối đa:</strong> <code>2^n − 2</code></li>\n            <li><strong>Số subnet:</strong> <code>2^m</code></li>\n          </ul>\n          <p>Trong đó <code>n</code> là số bit host còn lại, <code>m</code> là số bit mượn.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các thông số kỹ thuật cần nhớ</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">a. Subnet Mask phổ biến</span>\n          <table class=\"comparison-table\">\n            <thead>\n              <tr>\n                <th>CIDR</th>\n                <th>Subnet Mask</th>\n                <th>Số host</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>/24</td>\n                <td>255.255.255.0</td>\n                <td>254</td>\n              </tr>\n              <tr>\n                <td>/25</td>\n                <td>255.255.255.128</td>\n                <td>126</td>\n              </tr>\n              <tr>\n                <td>/26</td>\n                <td>255.255.255.192</td>\n                <td>62</td>\n              </tr>\n              <tr>\n                <td>/27</td>\n                <td>255.255.255.224</td>\n                <td>30</td>\n              </tr>\n              <tr>\n                <td>/28</td>\n                <td>255.255.255.240</td>\n                <td>14</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">b. Cách tính nhanh</span>\n          <blockquote>Bước nhảy = 256 − Octet của Subnet Mask</blockquote>\n          <p>Ví dụ:</p>\n          <ul>\n            <li>Mask: <code>255.255.255.192</code></li>\n            <li>Bước nhảy: <code>256 − 192 = 64</code></li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: Chia 192.168.1.0/24 thành 4 subnet</h2>\n      <div class=\"case-study\">\n        <div>\n          <p><strong>Bước 1:</strong> Cần 4 subnet → mượn 2 bit → <code>/24 → /26</code>.</p>\n          <p><strong>Bước 2:</strong> Mask: <code>255.255.255.192</code>, bước nhảy: <code>64</code>.</p>\n          <p><strong>Bước 3:</strong> Các subnet:</p>\n          <table class=\"comparison-table\">\n            <thead>\n              <tr>\n                <th>Subnet</th>\n                <th>Network</th>\n                <th>Usable IP</th>\n                <th>Broadcast</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>1</td>\n                <td>192.168.1.0</td>\n                <td>.1 – .62</td>\n                <td>.63</td>\n              </tr>\n              <tr>\n                <td>2</td>\n                <td>192.168.1.64</td>\n                <td>.65 – .126</td>\n                <td>.127</td>\n              </tr>\n              <tr>\n                <td>3</td>\n                <td>192.168.1.128</td>\n                <td>.129 – .190</td>\n                <td>.191</td>\n              </tr>\n              <tr>\n                <td>4</td>\n                <td>192.168.1.192</td>\n                <td>.193 – .254</td>\n                <td>.255</td>\n              </tr>\n            </tbody>\n          </table>\n          <p>👉 Mỗi subnet có <strong>62 host</strong>.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Gợi ý:</strong>\n          <p>Khi chia subnet, hãy xác định số subnet trước, sau đó tính bước nhảy để chia nhanh.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập thực hành</h2>\n      <h3>5.1. Tổng kết kiến thức</h3>\n      <ul>\n        <li>Subnet Mask giúp <strong>chia mạng con</strong>.</li>\n        <li>Chia subnet = mượn bit Host.</li>\n        <li>Luôn có Network Address và Broadcast Address.</li>\n        <li>Công thức nhanh: Host = <code>2^n − 2</code>, Bước nhảy = <code>256 − Mask</code>.</li>\n      </ul>\n      <p>👉 Chia subnet tốt = mạng gọn, nhanh, dễ quản lý.</p>\n      <div class=\"callout\">\n        <strong>5.2. Bài tập về nhà:</strong>\n        <p>Cho mạng <code>192.168.10.0/24</code>:</p>\n        <ol>\n          <li>Chia thành <strong>8 subnet</strong>.</li>\n          <li>Xác định Subnet Mask, Network Address của subnet thứ 5, dải IP sử dụng được.</li>\n          <li>Mỗi subnet có bao nhiêu host?</li>\n        </ol>\n        <p>📌 Trình bày từng bước, không cần nhị phân.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "15": {
    "title": "Bài 15: Tìm hiểu về địa chỉ IPv6 - Tương lai của internet.",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 15</p>\n        <h1>Tìm hiểu về địa chỉ IPv6 - Tương lai của internet</h1>\n        <p>\n          Bài học giải thích vì sao IPv6 ra đời, cấu trúc và cách viết địa chỉ IPv6, sự khác biệt giữa IPv4 và IPv6,\n          cùng các loại địa chỉ phổ biến trong Internet hiện đại.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>128 bit</strong>\n            Độ dài địa chỉ IPv6\n          </div>\n          <div class=\"stat\">\n            <strong>5 mục tiêu</strong>\n            Trọng tâm bài học\n          </div>\n          <div class=\"stat\">\n            <strong>2 bảng</strong>\n            So sánh quan trọng\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu vì sao IPv6 ra đời và nhu cầu thực tế của Internet hiện đại.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Nắm cấu trúc và cách viết địa chỉ IPv6.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Phân biệt IPv4 và IPv6 qua các tiêu chí quan trọng.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Hiểu các loại địa chỉ IPv6 phổ biến trong thực tế.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Nhận thức vai trò của IPv6 trong Internet hiện đại.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Đặt vấn đề</p>\n      <h2>Internet mở rộng thế nào khi IPv4 đã cạn?</h2>\n      <p>Số lượng thiết bị Internet tăng mạnh:</p>\n      <ul>\n        <li>Smartphone</li>\n        <li>IoT</li>\n        <li>Camera, Smart TV, xe thông minh</li>\n      </ul>\n      <p>IPv4 chỉ có khoảng 4,3 tỷ địa chỉ.</p>\n      <div class=\"highlight-card\">\n        <strong>Thực tế:</strong>\n        <blockquote>IPv4 đã cạn kiệt ở nhiều khu vực trên thế giới.</blockquote>\n        <strong>Câu hỏi:</strong>\n        <blockquote>Internet sẽ mở rộng bằng cách nào khi không còn đủ địa chỉ IP?</blockquote>\n        <p>Câu trả lời là <strong>IPv6</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>IPv6 là gì và vì sao quan trọng?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p><strong>IPv6 (Internet Protocol version 6)</strong> là phiên bản IP thế hệ mới.</p>\n          <ul>\n            <li>Được thiết kế để thay thế IPv4.</li>\n            <li>Hoạt động ở Layer 3 (Network Layer).</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🎯 Mục tiêu chính</span>\n          <ul>\n            <li>Giải quyết vấn đề cạn địa chỉ IPv4.</li>\n            <li>Đơn giản hóa định tuyến.</li>\n            <li>Hỗ trợ Internet quy mô toàn cầu.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🌐 Không gian địa chỉ</span>\n          <ul>\n            <li>IPv4: 32 bit → ~4,3 × 10⁹ địa chỉ.</li>\n            <li>IPv6: 128 bit → ~3,4 × 10³⁸ địa chỉ (gần như vô hạn).</li>\n          </ul>\n          <p>Mỗi thiết bị có thể có IP Public riêng, không cần NAT.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Cấu trúc, rút gọn và khám phá lân cận</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>a. Cấu trúc địa chỉ IPv6</h3>\n          <ul>\n            <li>Độ dài: 128 bit.</li>\n            <li>Viết dưới dạng hexadecimal.</li>\n            <li>Chia thành 8 block, mỗi block 16 bit.</li>\n          </ul>\n          <p><strong>Ví dụ:</strong></p>\n          <pre class=\"code-block\"><code>2001:0db8:85a3:0000:0000:8a2e:0370:7334</code></pre>\n        </div>\n        <div class=\"component-card\">\n          <h3>b. Quy tắc rút gọn IPv6</h3>\n          <ol>\n            <li>Bỏ số 0 ở đầu block.</li>\n            <li>Dãy block toàn 0 liên tiếp → :: (chỉ dùng 1 lần).</li>\n          </ol>\n          <pre class=\"code-block\"><code>0db8 → db8</code></pre>\n          <pre class=\"code-block\"><code>2001:db8::1</code></pre>\n        </div>\n        <div class=\"component-card\">\n          <h3>c. IPv6 không cần ARP</h3>\n          <ul>\n            <li>IPv6 dùng <strong>NDP (Neighbor Discovery Protocol)</strong>.</li>\n            <li>Dựa trên <strong>ICMPv6</strong>.</li>\n            <li>Tự động phát hiện thiết bị, router, MAC Address.</li>\n          </ul>\n          <p>👉 IPv6 hiện đại và thông minh hơn IPv4.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>Các bảng so sánh quan trọng</h2>\n      <div class=\"table-block\">\n        <h3>a. So sánh IPv4 và IPv6</h3>\n        <table>\n          <thead>\n            <tr>\n              <th>Tiêu chí</th>\n              <th>IPv4</th>\n              <th>IPv6</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td>Độ dài</td>\n              <td>32 bit</td>\n              <td>128 bit</td>\n            </tr>\n            <tr>\n              <td>Dạng</td>\n              <td>Thập phân</td>\n              <td>Hex</td>\n            </tr>\n            <tr>\n              <td>NAT</td>\n              <td>Cần</td>\n              <td>Không cần</td>\n            </tr>\n            <tr>\n              <td>ARP</td>\n              <td>Có</td>\n              <td>Không</td>\n            </tr>\n            <tr>\n              <td>Bảo mật</td>\n              <td>Tuỳ chọn</td>\n              <td>Tích hợp IPsec</td>\n            </tr>\n            <tr>\n              <td>Cấu hình</td>\n              <td>Thủ công / DHCP</td>\n              <td>Tự động (SLAAC)</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"table-block\">\n        <h3>b. Các loại địa chỉ IPv6 phổ biến</h3>\n        <table>\n          <thead>\n            <tr>\n              <th>Loại</th>\n              <th>Ý nghĩa</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td>Global Unicast</td>\n              <td>IP Public</td>\n            </tr>\n            <tr>\n              <td>Link-local</td>\n              <td>Giao tiếp trong LAN</td>\n            </tr>\n            <tr>\n              <td>Multicast</td>\n              <td>Gửi cho nhiều thiết bị</td>\n            </tr>\n            <tr>\n              <td>Anycast</td>\n              <td>Gửi tới node gần nhất</td>\n            </tr>\n          </tbody>\n        </table>\n        <p><strong>Không tồn tại Broadcast trong IPv6.</strong></p>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: Mạng doanh nghiệp hiện đại</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>Router hỗ trợ IPv6.</p>\n          <p>Máy tính nhận IP tự động.</p>\n          <p>Mỗi thiết bị có <strong>Global IPv6 riêng</strong>.</p>\n          <p><strong>Lợi ích:</strong></p>\n          <ul>\n            <li>Không cần NAT.</li>\n            <li>Kết nối trực tiếp.</li>\n            <li>Định tuyến hiệu quả.</li>\n            <li>Sẵn sàng IoT &amp; Cloud.</li>\n          </ul>\n        </div>\n        <div class=\"callout\">\n          <strong>IPv6 phù hợp cho:</strong>\n          <ul>\n            <li>Data Center</li>\n            <li>ISP</li>\n            <li>Smart City</li>\n            <li>5G / IoT</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập</h2>\n      <p><strong>Tổng kết kiến thức:</strong></p>\n      <ul>\n        <li>IPv6 là tương lai tất yếu của Internet.</li>\n        <li>Giải quyết triệt để vấn đề cạn IP.</li>\n        <li>Địa chỉ dài 128 bit.</li>\n        <li>Không cần ARP, không Broadcast.</li>\n        <li>Hỗ trợ bảo mật và tự động cấu hình.</li>\n      </ul>\n      <p><strong>IPv6 không phải “có thể”, mà là “phải dùng”.</strong></p>\n      <div class=\"callout\">\n        <strong>Bài tập thực hành:</strong>\n        <p>Trên máy tính của bạn:</p>\n        <ol>\n          <li>Kiểm tra xem máy có IPv6 không.</li>\n          <li>Ghi lại địa chỉ IPv6 và loại địa chỉ (Link-local hay Global).</li>\n          <li>Trả lời: Máy có nhiều IPv6 không? Vì sao IPv6 không cần NAT?</li>\n        </ol>\n        <p><strong>Gợi ý lệnh:</strong></p>\n        <ul>\n          <li>Windows: <code>ipconfig</code></li>\n          <li>Linux / macOS: <code>ip a</code></li>\n        </ul>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "16": {
    "title": "Bài 16: Định tuyến (Routing) là gì? Static vs Dynamic Routing",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 16</p>\n        <h1>Định tuyến (Routing) là gì? Static vs Dynamic Routing</h1>\n        <p>\n          Bài học giải thích cách router chọn đường đi cho gói tin, vai trò của routing table, default route và sự khác biệt\n          giữa định tuyến tĩnh và định tuyến động trong thực tế.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>5 mục tiêu</strong>\n            Nền tảng routing\n          </div>\n          <div class=\"stat\">\n            <strong>2 loại</strong>\n            Static vs Dynamic\n          </div>\n          <div class=\"stat\">\n            <strong>1 bảng</strong>\n            So sánh tổng hợp\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu định tuyến (Routing) là gì.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Biết vai trò của router trong mạng.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Phân biệt Static Routing và Dynamic Routing.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Hiểu khi nào nên dùng Static, khi nào dùng Dynamic.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Chuẩn bị nền tảng cho Routing Protocols (RIP, OSPF, BGP).</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Đặt vấn đề</p>\n      <h2>Làm sao router biết phải gửi gói tin đi đâu?</h2>\n      <p>Máy tính của bạn gửi dữ liệu ra Internet và dữ liệu phải đi qua:</p>\n      <ul>\n        <li>Router gia đình</li>\n        <li>Router của ISP</li>\n        <li>Nhiều router trung gian khác</li>\n      </ul>\n      <p>Cuối cùng mới đến server đích.</p>\n      <div class=\"highlight-card\">\n        <strong>Câu hỏi:</strong>\n        <blockquote>Làm sao mỗi router biết phải chuyển gói tin đi đâu tiếp theo khi có rất nhiều mạng khác nhau?</blockquote>\n        <p>Câu trả lời là <strong>Routing (Định tuyến)</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Routing và vai trò của Routing Table</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p><strong>Routing</strong> là quá trình lựa chọn đường đi tốt nhất cho gói tin từ mạng nguồn đến mạng đích.</p>\n          <ul>\n            <li>Thực hiện bởi router.</li>\n            <li>Hoạt động ở Layer 3 (Network Layer).</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🔁 Routing vs Switching</span>\n          <ul>\n            <li>Switching → trong cùng mạng.</li>\n            <li>Routing → giữa các mạng khác nhau.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧭 Routing Table</span>\n          <p>Router sử dụng routing table để quyết định đường đi.</p>\n          <ul>\n            <li>Network đích</li>\n            <li>Next-hop</li>\n            <li>Interface</li>\n            <li>Metric (độ ưu tiên)</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Quy trình định tuyến cơ bản</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. Nhận gói tin</strong>\n          Router nhận IP Packet.\n        </div>\n        <div class=\"step\">\n          <strong>2. Đọc IP đích</strong>\n          Xác định địa chỉ IP mục tiêu.\n        </div>\n        <div class=\"step\">\n          <strong>3. So khớp</strong>\n          So khớp với routing table.\n        </div>\n        <div class=\"step\">\n          <strong>4. Chọn tuyến</strong>\n          Chọn tuyến đường phù hợp nhất.\n        </div>\n        <div class=\"step\">\n          <strong>5. Chuyển tiếp</strong>\n          Chuyển packet sang router tiếp theo.\n        </div>\n      </div>\n      <p>📌 Router không quan tâm MAC cuối, chỉ quan tâm IP Network.</p>\n      <div class=\"callout\">\n        <strong>Default Route</strong>\n        <p>Dùng khi không có route cụ thể.</p>\n        <p>Ký hiệu:</p>\n        <pre class=\"code-block\"><code>0.0.0.0/0</code></pre>\n        <p>👉 “Không biết đi đâu thì đi theo đường này”.</p>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">So sánh</p>\n      <h2>Static Routing vs Dynamic Routing</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">🧊 Static Routing</span>\n          <p><strong>Khái niệm:</strong> Route được cấu hình thủ công, không tự động thay đổi.</p>\n          <p><strong>Phù hợp:</strong></p>\n          <ul>\n            <li>Mạng nhỏ</li>\n            <li>Route mặc định</li>\n            <li>Lab, test</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">⚡ Dynamic Routing</span>\n          <p><strong>Khái niệm:</strong> Router tự động học route thông qua routing protocol.</p>\n          <p><strong>Ví dụ:</strong></p>\n          <ul>\n            <li>RIP</li>\n            <li>OSPF</li>\n            <li>EIGRP</li>\n            <li>BGP</li>\n          </ul>\n        </div>\n      </div>\n\n      <div class=\"table-block\">\n        <h3>Ưu điểm / Nhược điểm của Static Routing</h3>\n        <table>\n          <thead>\n            <tr>\n              <th>Ưu điểm</th>\n              <th>Nhược điểm</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td>Đơn giản</td>\n              <td>Không linh hoạt</td>\n            </tr>\n            <tr>\n              <td>Bảo mật</td>\n              <td>Không tự thích nghi</td>\n            </tr>\n            <tr>\n              <td>Ít tài nguyên</td>\n              <td>Khó quản lý khi mạng lớn</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <div class=\"table-block\">\n        <h3>Ưu điểm / Nhược điểm của Dynamic Routing</h3>\n        <table>\n          <thead>\n            <tr>\n              <th>Ưu điểm</th>\n              <th>Nhược điểm</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td>Tự động</td>\n              <td>Phức tạp</td>\n            </tr>\n            <tr>\n              <td>Linh hoạt</td>\n              <td>Tốn tài nguyên</td>\n            </tr>\n            <tr>\n              <td>Phù hợp mạng lớn</td>\n              <td>Cần kiến thức</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <div class=\"table-block\">\n        <h3>So sánh tổng hợp</h3>\n        <table>\n          <thead>\n            <tr>\n              <th>Tiêu chí</th>\n              <th>Static</th>\n              <th>Dynamic</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td>Cấu hình</td>\n              <td>Thủ công</td>\n              <td>Tự động</td>\n            </tr>\n            <tr>\n              <td>Mở rộng</td>\n              <td>Kém</td>\n              <td>Tốt</td>\n            </tr>\n            <tr>\n              <td>Phản ứng khi lỗi</td>\n              <td>Không</td>\n              <td>Có</td>\n            </tr>\n            <tr>\n              <td>Độ phức tạp</td>\n              <td>Thấp</td>\n              <td>Cao</td>\n            </tr>\n            <tr>\n              <td>Ứng dụng</td>\n              <td>Mạng nhỏ</td>\n              <td>Mạng lớn</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: chọn loại định tuyến phù hợp</h2>\n      <div class=\"case-study\">\n        <div>\n          <h3>Case 1: Mạng văn phòng nhỏ</h3>\n          <ul>\n            <li>1 router</li>\n            <li>2 network</li>\n            <li>Static Routing</li>\n            <li>Đơn giản, dễ kiểm soát</li>\n          </ul>\n        </div>\n        <div class=\"callout\">\n          <h3>Case 2: Mạng doanh nghiệp / ISP</h3>\n          <ul>\n            <li>Hàng chục router</li>\n            <li>Nhiều đường dự phòng</li>\n            <li>Dynamic Routing</li>\n            <li>Router tự học đường, tự chuyển hướng khi có sự cố</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập</h2>\n      <p><strong>Tổng kết kiến thức:</strong></p>\n      <ul>\n        <li>Routing = chọn đường đi cho gói tin.</li>\n        <li>Router hoạt động ở Layer 3.</li>\n        <li>Routing Table quyết định đường đi.</li>\n        <li>Static: đơn giản, thủ công.</li>\n        <li>Dynamic: tự động, linh hoạt.</li>\n        <li>Routing là xương sống của Internet.</li>\n      </ul>\n      <div class=\"callout\">\n        <strong>Bài tập về nhà:</strong>\n        <p>Giả sử bạn có:</p>\n        <ul>\n          <li>Mạng A: <code>192.168.1.0/24</code></li>\n          <li>Mạng B: <code>192.168.2.0/24</code></li>\n        </ul>\n        <ol>\n          <li>Có cần Routing không? Vì sao?</li>\n          <li>Dùng Static hay Dynamic Routing?</li>\n          <li>Nếu thêm mạng C, D, E… thì sao?</li>\n        </ol>\n        <p>📌 Trả lời ngắn gọn 6–8 dòng.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "17": {
    "title": "Bài 17: Các giao thức định tuyến phổ biến (RIP, OSPF, BGP).",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 17</p>\n        <h1>Các giao thức định tuyến phổ biến (RIP, OSPF, BGP)</h1>\n        <p>\n          Bài học giúp bạn hiểu routing protocol là gì, cách phân biệt RIP, OSPF và BGP, phạm vi sử dụng\n          và vì sao chúng là nền tảng của mạng doanh nghiệp lẫn Internet toàn cầu.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>3 giao thức</strong>\n            RIP · OSPF · BGP\n          </div>\n          <div class=\"stat\">\n            <strong>2 nhóm</strong>\n            IGP &amp; EGP\n          </div>\n          <div class=\"stat\">\n            <strong>1 bảng</strong>\n            So sánh tổng hợp\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu giao thức định tuyến (Routing Protocol) là gì.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Phân biệt được RIP, OSPF và BGP.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Biết phạm vi sử dụng của từng giao thức.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Hiểu vì sao doanh nghiệp dùng OSPF, Internet dùng BGP.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Chuẩn bị nền tảng cho cấu hình routing thực tế.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Đặt vấn đề</p>\n      <h2>Làm sao router tự cập nhật đường đi tốt nhất?</h2>\n      <p>Một mạng có nhiều router và nhiều đường đi khác nhau:</p>\n      <ul>\n        <li>Bị đứt</li>\n        <li>Bị nghẽn</li>\n        <li>Bị chậm</li>\n      </ul>\n      <div class=\"highlight-card\">\n        <strong>Câu hỏi:</strong>\n        <blockquote>Làm sao router tự động cập nhật đường đi tốt nhất mà không cần con người cấu hình lại từng route?</blockquote>\n        <p>Câu trả lời là <strong>Routing Protocols (Giao thức định tuyến)</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Routing Protocol là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p><strong>Routing Protocol</strong> là tập hợp quy tắc giúp router:</p>\n          <ul>\n            <li>Trao đổi thông tin mạng</li>\n            <li>Học các tuyến đường mới</li>\n            <li>Cập nhật routing table tự động</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🔁 Routing vs Protocol</span>\n          <ul>\n            <li>Routing: quá trình chuyển gói tin.</li>\n            <li>Routing Protocol: cách router học đường.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧭 Phân loại</span>\n          <table>\n            <thead>\n              <tr>\n                <th>Nhóm</th>\n                <th>Phạm vi</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>IGP (Interior Gateway Protocol)</td>\n                <td>Trong một hệ thống</td>\n              </tr>\n              <tr>\n                <td>EGP (Exterior Gateway Protocol)</td>\n                <td>Giữa các hệ thống</td>\n              </tr>\n            </tbody>\n          </table>\n          <p>📌 RIP, OSPF → IGP · BGP → EGP</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Đặc điểm chính của RIP, OSPF và BGP</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>a. RIP – Routing Information Protocol</h3>\n          <p><strong>Đặc điểm chính:</strong></p>\n          <ul>\n            <li>Dựa trên Hop Count</li>\n            <li>Tối đa 15 hop</li>\n            <li>Gửi bảng định tuyến định kỳ</li>\n          </ul>\n          <p>📌 Nếu hop &gt; 15 → không dùng được.</p>\n          <div class=\"table-block\">\n            <table>\n              <thead>\n                <tr>\n                  <th>Ưu điểm</th>\n                  <th>Nhược điểm</th>\n                </tr>\n              </thead>\n              <tbody>\n                <tr>\n                  <td>Dễ hiểu</td>\n                  <td>Chậm</td>\n                </tr>\n                <tr>\n                  <td>Dễ cấu hình</td>\n                  <td>Không mở rộng</td>\n                </tr>\n                <tr>\n                  <td>Phù hợp học tập</td>\n                  <td>Lỗi thời</td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n          <p>📌 Phù hợp: mạng rất nhỏ, lab.</p>\n        </div>\n        <div class=\"component-card\">\n          <h3>b. OSPF – Open Shortest Path First</h3>\n          <p><strong>Đặc điểm chính:</strong></p>\n          <ul>\n            <li>Dựa trên Cost (băng thông)</li>\n            <li>Thuật toán Dijkstra</li>\n            <li>Chia mạng thành Area</li>\n            <li>Cập nhật khi có thay đổi</li>\n          </ul>\n          <p>📌 Router có bản đồ toàn mạng.</p>\n          <div class=\"table-block\">\n            <table>\n              <thead>\n                <tr>\n                  <th>Ưu điểm</th>\n                  <th>Nhược điểm</th>\n                </tr>\n              </thead>\n              <tbody>\n                <tr>\n                  <td>Nhanh</td>\n                  <td>Phức tạp</td>\n                </tr>\n                <tr>\n                  <td>Mở rộng tốt</td>\n                  <td>Cần kiến thức</td>\n                </tr>\n                <tr>\n                  <td>Chuẩn doanh nghiệp</td>\n                  <td></td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n          <p>📌 Phù hợp: mạng doanh nghiệp, campus network.</p>\n        </div>\n        <div class=\"component-card\">\n          <h3>c. BGP – Border Gateway Protocol</h3>\n          <p><strong>Đặc điểm chính:</strong></p>\n          <ul>\n            <li>Định tuyến giữa các Autonomous System (AS)</li>\n            <li>Dựa trên Policy, không phải tốc độ</li>\n            <li>Dùng cho Internet</li>\n          </ul>\n          <blockquote>“Dữ liệu đi qua ai, không phải đi nhanh nhất”</blockquote>\n          <div class=\"table-block\">\n            <table>\n              <thead>\n                <tr>\n                  <th>Ưu điểm</th>\n                  <th>Nhược điểm</th>\n                </tr>\n              </thead>\n              <tbody>\n                <tr>\n                  <td>Rất linh hoạt</td>\n                  <td>Rất phức tạp</td>\n                </tr>\n                <tr>\n                  <td>Internet backbone</td>\n                  <td>Cấu hình khó</td>\n                </tr>\n                <tr>\n                  <td>Kiểm soát cao</td>\n                  <td></td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n          <p>📌 Phù hợp: ISP, Data Center, Internet backbone.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Thông số</p>\n      <h2>So sánh tổng hợp RIP – OSPF – BGP</h2>\n      <table>\n        <thead>\n          <tr>\n            <th>Tiêu chí</th>\n            <th>RIP</th>\n            <th>OSPF</th>\n            <th>BGP</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Loại</td>\n            <td>IGP</td>\n            <td>IGP</td>\n            <td>EGP</td>\n          </tr>\n          <tr>\n            <td>Metric</td>\n            <td>Hop Count</td>\n            <td>Cost</td>\n            <td>Policy</td>\n          </tr>\n          <tr>\n            <td>Tốc độ hội tụ</td>\n            <td>Chậm</td>\n            <td>Nhanh</td>\n            <td>Chậm</td>\n          </tr>\n          <tr>\n            <td>Quy mô</td>\n            <td>Nhỏ</td>\n            <td>Trung bình–Lớn</td>\n            <td>Rất lớn</td>\n          </tr>\n          <tr>\n            <td>Mức độ</td>\n            <td>Cơ bản</td>\n            <td>Trung cấp</td>\n            <td>Nâng cao</td>\n          </tr>\n          <tr>\n            <td>Thực tế</td>\n            <td>Hiếm</td>\n            <td>Phổ biến</td>\n            <td>Bắt buộc</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: chọn giao thức phù hợp</h2>\n      <div class=\"case-study\">\n        <div>\n          <h3>Case 1: Mạng phòng lab / lớp học</h3>\n          <ul>\n            <li>3–4 router</li>\n            <li>Mục tiêu: học nguyên lý</li>\n            <li>RIP</li>\n            <li>Dễ hiểu, dễ cấu hình</li>\n          </ul>\n        </div>\n        <div>\n          <h3>Case 2: Mạng doanh nghiệp</h3>\n          <ul>\n            <li>Nhiều chi nhánh</li>\n            <li>Yêu cầu ổn định, nhanh</li>\n            <li>OSPF</li>\n            <li>Hội tụ nhanh, chia Area dễ quản lý</li>\n          </ul>\n        </div>\n        <div class=\"callout\">\n          <h3>Case 3: ISP kết nối Internet</h3>\n          <ul>\n            <li>Kết nối nhiều nhà mạng</li>\n            <li>Điều khiển luồng Internet</li>\n            <li>BGP</li>\n            <li>Tiêu chuẩn toàn cầu, không thể thay thế</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập</h2>\n      <p><strong>Tổng kết kiến thức:</strong></p>\n      <ul>\n        <li>Routing Protocol giúp router tự học đường đi.</li>\n        <li>RIP: đơn giản, lỗi thời.</li>\n        <li>OSPF: chuẩn doanh nghiệp.</li>\n        <li>BGP: xương sống Internet.</li>\n      </ul>\n      <p><strong>Không có BGP → không có Internet toàn cầu.</strong></p>\n      <div class=\"callout\">\n        <strong>Bài tập về nhà:</strong>\n        <p>Với từng hệ thống sau, hãy chọn giao thức phù hợp và giải thích:</p>\n        <ol>\n          <li>Mạng gia đình mở rộng nhiều tầng</li>\n          <li>Mạng doanh nghiệp có 5 chi nhánh</li>\n          <li>Mạng của nhà cung cấp Internet (ISP)</li>\n        </ol>\n        <p>📌 Mỗi câu trả lời 2–3 dòng.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "18": {
    "title": "Bài 18: Công nghệ NAT (Network Address Translation).",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 18</p>\n        <h1>Công nghệ NAT (Network Address Translation)</h1>\n        <p>\n          Bài học giới thiệu NAT là gì, vì sao NAT ra đời, cách mạng private truy cập Internet, các loại NAT phổ biến\n          và vai trò của NAT trong IPv4.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#content\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>3 loại</strong>\n            Static · Dynamic · PAT\n          </div>\n          <div class=\"stat\">\n            <strong>1 bảng</strong>\n            So sánh nhanh\n          </div>\n          <div class=\"stat\">\n            <strong>IPv4</strong>\n            NAT là giải pháp then chốt\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section>\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu NAT là gì và vì sao NAT ra đời.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Phân biệt các loại NAT phổ biến.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Hiểu cách mạng Private truy cập Internet.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Nhận biết vai trò của NAT trong IPv4.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Chuẩn bị nền tảng cho PAT, Firewall, IPv6.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Đặt vấn đề</p>\n      <h2>Làm sao nhiều thiết bị dùng chung một IP Public?</h2>\n      <p>Gia đình bạn có:</p>\n      <ul>\n        <li>1 modem / router</li>\n        <li>Nhiều thiết bị: laptop, điện thoại, TV</li>\n      </ul>\n      <p>Nhà mạng chỉ cấp 1 IP Public.</p>\n      <div class=\"highlight-card\">\n        <strong>Câu hỏi:</strong>\n        <blockquote>Làm sao nhiều thiết bị private cùng truy cập Internet thông qua 1 IP Public duy nhất?</blockquote>\n        <p>Câu trả lời là <strong>NAT</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"content\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>NAT là gì và vì sao cần NAT?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 NAT là gì?</span>\n          <p><strong>NAT (Network Address Translation)</strong> là công nghệ chuyển đổi địa chỉ IP Private ↔ IP Public.</p>\n          <ul>\n            <li>Thực hiện trên router hoặc firewall.</li>\n            <li>Hoạt động ở Layer 3 &amp; Layer 4.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✅ NAT giúp</span>\n          <ul>\n            <li>Tiết kiệm IPv4.</li>\n            <li>Tăng bảo mật cơ bản.</li>\n            <li>Kéo dài tuổi thọ IPv4.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">❓ Vì sao cần NAT</span>\n          <ul>\n            <li>IPv4 cạn kiệt.</li>\n            <li>Số thiết bị tăng nhanh.</li>\n            <li>Không thể cấp IP Public cho mọi thiết bị.</li>\n          </ul>\n          <p>👉 NAT là giải pháp tạm thời nhưng cực kỳ hiệu quả.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Cách NAT dịch địa chỉ</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. Gửi ra ngoài</strong>\n          Thiết bị private gửi packet ra Internet.\n        </div>\n        <div class=\"step\">\n          <strong>2. Dịch địa chỉ</strong>\n          Router thay IP nguồn Private → IP Public.\n        </div>\n        <div class=\"step\">\n          <strong>3. Lưu bảng</strong>\n          Router lưu thông tin vào NAT Table.\n        </div>\n        <div class=\"step\">\n          <strong>4. Nhận phản hồi</strong>\n          Server Internet trả dữ liệu về IP Public.\n        </div>\n        <div class=\"step\">\n          <strong>5. Dịch ngược</strong>\n          Router dịch ngược → IP Private ban đầu.\n        </div>\n      </div>\n      <p>📌 Người ngoài không thấy IP nội bộ.</p>\n      <div class=\"callout\">\n        <strong>NAT Table lưu:</strong>\n        <ul>\n          <li>IP Private</li>\n          <li>IP Public</li>\n          <li>Port (nếu có)</li>\n        </ul>\n        <p>Giúp router gửi dữ liệu đúng thiết bị.</p>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Các loại NAT</p>\n      <h2>Static, Dynamic và PAT</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>a. Static NAT</h3>\n          <p>1 IP Private ↔ 1 IP Public (cố định).</p>\n          <p><strong>Dùng cho:</strong></p>\n          <ul>\n            <li>Server nội bộ</li>\n            <li>Camera</li>\n            <li>Web server</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>b. Dynamic NAT</h3>\n          <p>IP Private ↔ IP Public (lấy từ pool).</p>\n          <p>📌 Ít dùng trong gia đình.</p>\n        </div>\n        <div class=\"component-card\">\n          <h3>c. PAT (NAT Overload)</h3>\n          <p>Nhiều IP Private → 1 IP Public.</p>\n          <p>Phân biệt bằng Port.</p>\n          <p>📌 Đây là NAT phổ biến nhất hiện nay.</p>\n        </div>\n      </div>\n      <div class=\"table-block\">\n        <h3>d. So sánh nhanh</h3>\n        <table>\n          <thead>\n            <tr>\n              <th>Loại NAT</th>\n              <th>IP Public</th>\n              <th>Số thiết bị</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td>Static</td>\n              <td>1</td>\n              <td>1</td>\n            </tr>\n            <tr>\n              <td>Dynamic</td>\n              <td>N</td>\n              <td>≤ N</td>\n            </tr>\n            <tr>\n              <td>PAT</td>\n              <td>1</td>\n              <td>Rất nhiều</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: Mạng gia đình</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>Router có IP Public: <code>113.x.x.x</code></p>\n          <p>Thiết bị:</p>\n          <ul>\n            <li>Laptop: <code>192.168.1.10</code></li>\n            <li>Phone: <code>192.168.1.20</code></li>\n          </ul>\n        </div>\n        <div class=\"callout\">\n          <strong>Quá trình:</strong>\n          <ul>\n            <li><code>192.168.1.10:5000 → 113.x.x.x:40001</code></li>\n            <li><code>192.168.1.20:5001 → 113.x.x.x:40002</code></li>\n          </ul>\n          <p>👉 Router dùng <strong>PAT</strong> để phân biệt.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết &amp; bài tập</h2>\n      <p><strong>Tổng kết kiến thức:</strong></p>\n      <ul>\n        <li>NAT chuyển IP Private ↔ Public.</li>\n        <li>Giải quyết bài toán cạn IPv4.</li>\n        <li>NAT tạo lớp bảo mật cơ bản.</li>\n        <li>PAT là loại NAT phổ biến nhất.</li>\n        <li>IPv6 không cần NAT.</li>\n      </ul>\n      <p><strong>Không có NAT → Internet IPv4 không tồn tại đến hôm nay.</strong></p>\n      <div class=\"callout\">\n        <strong>Bài tập về nhà:</strong>\n        <p>Hãy trả lời:</p>\n        <ol>\n          <li>Vì sao NAT giúp tăng bảo mật?</li>\n          <li>Nhà bạn đang dùng loại NAT nào?</li>\n          <li>Nếu đặt Web Server trong LAN, cần NAT gì?</li>\n        </ol>\n        <p>📌 Mỗi câu 2–3 dòng.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "19": {
    "title": "Bài 19: TCP: Giao thức truyền tin tin cậy",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 19</p>\n        <h1>TCP: Giao thức truyền tin tin cậy</h1>\n        <p>\n          TCP giúp dữ liệu truyền qua Internet đầy đủ, đúng thứ tự và không bị mất. Bài học này giải thích vì sao TCP\n          là nền tảng cho email, tải file, giao dịch ngân hàng và nhiều ứng dụng quan trọng khác.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>5 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>Layer 4</strong>\n            Transport Layer\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu TCP là gì và vai trò của TCP trong truyền dữ liệu.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Giải thích vì sao TCP được gọi là giao thức tin cậy.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Nắm quy trình thiết lập và kết thúc kết nối TCP.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Phân biệt TCP và UDP khi chọn giao thức truyền.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Nhận diện các ứng dụng thực tế sử dụng TCP.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Nếu dữ liệu bị mất, đến sai thứ tự, thì email, tải file hay đăng nhập ngân hàng có hoạt động được không?\"\n        </blockquote>\n        <p>Câu trả lời nằm ở TCP - giao thức đảm bảo tính toàn vẹn dữ liệu.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>TCP là gì và đảm bảo điều gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p><strong>TCP (Transmission Control Protocol)</strong> là giao thức truyền dữ liệu tin cậy ở tầng vận chuyển.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧭 Đặc điểm</span>\n          <ul>\n            <li>Hướng kết nối (Connection-oriented).</li>\n            <li>Có xác nhận khi gửi và nhận dữ liệu.</li>\n            <li>Kiểm soát lỗi và luồng dữ liệu.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✅ TCP đảm bảo</span>\n          <ul>\n            <li>Đúng thứ tự.</li>\n            <li>Đầy đủ.</li>\n            <li>Không trùng lặp.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">So sánh</p>\n      <h2>TCP làm được gì mà IP không làm?</h2>\n      <div class=\"timeline\">\n        <article class=\"timeline-card\">\n          <h3>IP</h3>\n          <ul>\n            <li>Chỉ định tuyến gói tin.</li>\n            <li>Không đảm bảo dữ liệu đến đủ.</li>\n            <li>Không sắp xếp thứ tự.</li>\n            <li>Không kiểm soát lỗi & luồng.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>TCP</h3>\n          <ul>\n            <li>Truyền dữ liệu tin cậy.</li>\n            <li>Có xác nhận và truyền lại khi cần.</li>\n            <li>Sắp xếp dữ liệu theo thứ tự.</li>\n            <li>Kiểm soát lỗi, luồng, tắc nghẽn.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Cách TCP hoạt động</h2>\n      <p>TCP luôn đi qua chu trình thiết lập, truyền dữ liệu và kết thúc kết nối để đảm bảo dữ liệu được truyền chính xác.</p>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. Three-way Handshake</strong>\n          SYN → SYN-ACK → ACK để thiết lập kết nối.\n        </div>\n        <div class=\"step\">\n          <strong>2. Truyền dữ liệu tin cậy</strong>\n          Dữ liệu chia thành segment kèm Sequence/Ack, mất gói sẽ gửi lại.\n        </div>\n        <div class=\"step\">\n          <strong>3. Four-way Handshake</strong>\n          FIN/ACK trao đổi để đóng kết nối an toàn.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Cơ chế</p>\n      <h2>Ba cơ chế quan trọng của TCP</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>1. Kiểm soát lỗi</h3>\n          <ul>\n            <li>Checksum để phát hiện sai lệch.</li>\n            <li>ACK và retransmission khi mất gói.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>2. Kiểm soát luồng</h3>\n          <ul>\n            <li>Window Size để điều chỉnh tốc độ gửi.</li>\n            <li>Tránh làm tràn bộ đệm bên nhận.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>3. Kiểm soát tắc nghẽn</h3>\n          <ul>\n            <li>Slow Start và Congestion Avoidance.</li>\n            <li>TCP tự điều chỉnh tốc độ theo mạng.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: tải file qua HTTP/HTTPS</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>🌐 Trình duyệt mở kết nối TCP với máy chủ.</p>\n          <p>📦 File được chia thành nhiều segment có số thứ tự.</p>\n          <p>🔁 Nếu mất một segment, TCP yêu cầu gửi lại.</p>\n          <p>✅ Kết quả: file tải xong đúng 100% và không lỗi dữ liệu.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>TCP phù hợp cho các ứng dụng đòi hỏi tính toàn vẹn như email, ngân hàng, tải file.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Trả lời ngắn gọn 1-2 dòng cho mỗi câu:</p>\n      <ol>\n        <li>Gửi email có dùng TCP không? Vì sao?</li>\n        <li>Xem video YouTube có dùng TCP không? Vì sao?</li>\n        <li>Tải file phần mềm có dùng TCP không? Vì sao?</li>\n        <li>Game online có dùng TCP không? Vì sao?</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Hãy liên hệ yêu cầu về độ tin cậy, độ trễ và loại dữ liệu của từng ứng dụng.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "20": {
    "title": "Bài 20: UDP: Giao thức truyền tin nhanh (Streaming &amp; Gaming)",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 20</p>\n        <h1>UDP: Giao thức truyền tin nhanh</h1>\n        <p>\n          UDP ưu tiên tốc độ và độ trễ thấp cho các ứng dụng thời gian thực như streaming, game online và VoIP. Bài học\n          này giúp bạn hiểu vì sao UDP nhanh và đánh đổi điều gì so với TCP.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>20 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>5 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>Low latency</strong>\n            Ưu tiên tốc độ\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu UDP là gì và vai trò của UDP trong truyền dữ liệu thời gian thực.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Phân biệt rõ UDP và TCP theo tiêu chí tốc độ - độ tin cậy.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Giải thích vì sao streaming, game online và VoIP ưu tiên UDP.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Nắm ưu điểm, nhược điểm và đánh đổi của UDP.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Nhận diện các ứng dụng thực tế dùng UDP.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Mất vài gói tin có thể chấp nhận, nhưng delay vài giây thì không. Vậy chọn TCP hay UDP?\"\n        </blockquote>\n        <p>UDP ra đời để ưu tiên trải nghiệm thời gian thực.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>UDP là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p><strong>UDP (User Datagram Protocol)</strong> là giao thức truyền dữ liệu nhanh, không hướng kết nối.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧭 Đặc điểm</span>\n          <ul>\n            <li>Không thiết lập kết nối.</li>\n            <li>Không xác nhận (ACK).</li>\n            <li>Không tự gửi lại gói tin.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✅ Phù hợp</span>\n          <ul>\n            <li>Dữ liệu thời gian thực.</li>\n            <li>Ứng dụng ưu tiên tốc độ.</li>\n            <li>Tình huống chấp nhận mất gói.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">So sánh</p>\n      <h2>UDP khác TCP ở điểm nào?</h2>\n      <div class=\"timeline\">\n        <article class=\"timeline-card\">\n          <h3>TCP</h3>\n          <ul>\n            <li>Có kết nối, có xác nhận.</li>\n            <li>Đảm bảo đầy đủ và đúng thứ tự.</li>\n            <li>Nặng hơn, chậm hơn.</li>\n            <li>Phù hợp dữ liệu quan trọng.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>UDP</h3>\n          <ul>\n            <li>Không kết nối, không ACK.</li>\n            <li>Không đảm bảo dữ liệu đến đủ.</li>\n            <li>Nhẹ, nhanh, độ trễ thấp.</li>\n            <li>Phù hợp dữ liệu thời gian thực.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Cách UDP truyền dữ liệu</h2>\n      <p>UDP gửi datagram trực tiếp ra mạng và không chờ phản hồi, vì vậy tốc độ cao nhưng không đảm bảo.</p>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. Tạo datagram</strong>\n          Ứng dụng đóng gói dữ liệu thành UDP datagram.\n        </div>\n        <div class=\"step\">\n          <strong>2. Gửi ra mạng</strong>\n          Datagram được gửi ngay, không cần handshake.\n        </div>\n        <div class=\"step\">\n          <strong>3. Không chờ ACK</strong>\n          Không kiểm tra gói có đến hay không.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Kỹ thuật</p>\n      <h2>Ưu điểm & nhược điểm của UDP</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>Ưu điểm</h3>\n          <ul>\n            <li>Độ trễ thấp, phản hồi nhanh.</li>\n            <li>Ít overhead, header nhỏ.</li>\n            <li>Triển khai đơn giản.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Nhược điểm</h3>\n          <ul>\n            <li>Mất gói không biết.</li>\n            <li>Không đảm bảo thứ tự.</li>\n            <li>Ứng dụng phải tự xử lý lỗi nếu cần.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Ứng dụng phổ biến</h3>\n          <ul>\n            <li>Streaming video, livestream.</li>\n            <li>Game online.</li>\n            <li>VoIP, video call.</li>\n            <li>DNS, DHCP.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: livestream & game online</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>🎥 Livestream chia thành nhiều gói UDP.</p>\n          <p>🔁 Mất một vài gói: hình giật nhẹ nhưng không bị đứng hình.</p>\n          <p>🎮 Game online gửi liên tục vị trí nhân vật, gói cũ mất không quan trọng.</p>\n          <p>✅ UDP tối ưu cho trải nghiệm thời gian thực.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>UDP không kém TCP, mà phù hợp cho tình huống ưu tiên tốc độ.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Chọn TCP hay UDP cho mỗi tình huống và giải thích ngắn gọn:</p>\n      <ol>\n        <li>Xem YouTube livestream.</li>\n        <li>Tải file từ Google Drive.</li>\n        <li>Gọi video call với bạn bè.</li>\n        <li>Chat văn bản (Messenger).</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Ưu tiên tốc độ hay độ tin cậy sẽ quyết định giao thức.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "21": {
    "title": "Bài 21: Hệ thống phân giải tên miền (DNS)",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 21</p>\n        <h1>Hệ thống phân giải tên miền (DNS)</h1>\n        <p>\n          DNS là danh bạ của Internet, giúp chuyển tên miền dễ nhớ thành địa chỉ IP. Bài học này giải thích cách DNS\n          hoạt động, các thành phần và bản ghi quan trọng.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>5 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>DNS 53</strong>\n            UDP/TCP\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu DNS là gì và vai trò của DNS trong Internet.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Giải thích vì sao cần DNS thay vì dùng IP trực tiếp.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Mô tả quy trình phân giải tên miền.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Nhận biết các thành phần và bản ghi DNS phổ biến.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Hiểu mối liên hệ DNS - TCP/UDP - IP.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Làm sao Internet biết www.google.com tương ứng với IP nào để kết nối đúng máy chủ?\"\n        </blockquote>\n        <p>Câu trả lời chính là DNS.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>DNS là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p><strong>DNS (Domain Name System)</strong> chuyển đổi tên miền thành địa chỉ IP.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧭 Mô hình</span>\n          <ul>\n            <li>Client - Server.</li>\n            <li>Phân tán toàn cầu.</li>\n            <li>Hoạt động theo phân cấp.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✅ Lợi ích</span>\n          <ul>\n            <li>Dễ nhớ, dễ sử dụng.</li>\n            <li>Linh hoạt khi đổi IP.</li>\n            <li>Mở rộng Internet toàn cầu.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Quy trình phân giải tên miền</h2>\n      <p>Ví dụ truy cập <code>www.example.com</code>, DNS sẽ đi qua nhiều lớp để tìm đúng IP.</p>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>Bước 1</strong>\n          Client hỏi DNS Resolver.\n        </div>\n        <div class=\"step\">\n          <strong>Bước 2</strong>\n          Resolver hỏi Root DNS Server.\n        </div>\n        <div class=\"step\">\n          <strong>Bước 3</strong>\n          Root trả về TLD Server (.com).\n        </div>\n        <div class=\"step\">\n          <strong>Bước 4</strong>\n          TLD trả về Authoritative DNS Server.\n        </div>\n        <div class=\"step\">\n          <strong>Bước 5</strong>\n          Authoritative trả về IP chính xác.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Cấu trúc</p>\n      <h2>Phân cấp & bản ghi DNS</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>Cấu trúc phân cấp</h3>\n          <ul>\n            <li>Root: .</li>\n            <li>TLD: .com, .net, .vn</li>\n            <li>Domain: example.com</li>\n            <li>Host: www.example.com</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Bản ghi phổ biến</h3>\n          <ul>\n            <li>A: Domain → IPv4</li>\n            <li>AAAA: Domain → IPv6</li>\n            <li>CNAME: Alias</li>\n            <li>MX: Mail Server</li>\n            <li>NS: Name Server</li>\n            <li>TXT: Xác thực / SPF</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>DNS dùng TCP hay UDP?</h3>\n          <ul>\n            <li>UDP 53: truy vấn thông thường (nhanh).</li>\n            <li>TCP 53: zone transfer hoặc gói lớn.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: truy cập website công ty</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>🌐 Người dùng gõ <code>company.com</code>.</p>\n          <p>📌 DNS trả về IP tương ứng.</p>\n          <p>🔁 Server đổi IP: chỉ cần cập nhật DNS.</p>\n          <p>✅ Người dùng vẫn truy cập bằng tên cũ.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>DNS giúp tách biệt tên và IP, làm Internet linh hoạt và dễ dùng.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Thực hành nhanh trên máy tính của bạn:</p>\n      <ol>\n        <li>Mở Terminal / Command Prompt.</li>\n        <li>Chạy lệnh <code>nslookup google.com</code>.</li>\n        <li>Ghi lại IP trả về và DNS server đang dùng.</li>\n        <li>Thử đổi DNS sang <code>8.8.8.8</code> và kiểm tra lại.</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Trả lời ngắn gọn 5-7 dòng, tập trung vào DNS resolver bạn quan sát được.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "22": {
    "title": "Bài 22: Giao thức Web: HTTP và HTTPS",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 22</p>\n        <h1>Giao thức Web: HTTP và HTTPS</h1>\n        <p>\n          Mỗi lần bạn bấm vào một liên kết, HTTP/HTTPS chịu trách nhiệm đưa dữ liệu từ server về trình duyệt. Bài học\n          này giúp bạn hiểu cách web vận hành và vì sao HTTPS là tiêu chuẩn bắt buộc.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>6 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>Port 80/443</strong>\n            HTTP/HTTPS\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu HTTP và HTTPS là gì.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Nắm cách trình duyệt và web server giao tiếp.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Phân biệt HTTP và HTTPS.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Hiểu vai trò của mã hóa và chứng chỉ số.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Nhận diện các phương thức HTTP phổ biến.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Điều gì xảy ra phía sau khi bạn truy cập <code>http://example.com</code> hay <code>https://example.com</code>?\"\n        </blockquote>\n        <p>Câu trả lời nằm ở giao thức web và lớp bảo mật TLS.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>HTTP và HTTPS</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 HTTP</span>\n          <p>Giao thức truyền dữ liệu giữa trình duyệt và web server, chạy trên TCP port 80.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🔒 HTTPS</span>\n          <p>HTTP kết hợp TLS/SSL để mã hóa, xác thực và đảm bảo toàn vẹn dữ liệu trên port 443.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">⚠️ HTTP đặc trưng</span>\n          <ul>\n            <li>Stateless.</li>\n            <li>Không mã hóa dữ liệu.</li>\n            <li>Dễ bị nghe lén nếu dùng dữ liệu nhạy cảm.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Request - Response & TLS Handshake</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. HTTP Request</strong>\n          Trình duyệt gửi request (GET, POST...) đến server.\n        </div>\n        <div class=\"step\">\n          <strong>2. HTTP Response</strong>\n          Server trả về HTML/CSS/JS hoặc dữ liệu API.\n        </div>\n        <div class=\"step\">\n          <strong>3. TLS Handshake</strong>\n          Với HTTPS, client xác thực certificate và tạo khóa mã hóa.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">So sánh</p>\n      <h2>HTTP vs HTTPS</h2>\n      <div class=\"timeline\">\n        <article class=\"timeline-card\">\n          <h3>HTTP</h3>\n          <ul>\n            <li>Không mã hóa.</li>\n            <li>Dữ liệu dễ bị nghe lén.</li>\n            <li>Port 80.</li>\n            <li>Không có chứng chỉ số.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>HTTPS</h3>\n          <ul>\n            <li>Mã hóa dữ liệu.</li>\n            <li>Xác thực danh tính website.</li>\n            <li>Port 443.</li>\n            <li>Tiêu chuẩn bắt buộc của web hiện đại.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Kỹ thuật</p>\n      <h2>Phương thức HTTP & Status Code</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>HTTP Methods</h3>\n          <ul>\n            <li>GET: lấy dữ liệu.</li>\n            <li>POST: gửi dữ liệu.</li>\n            <li>PUT: cập nhật.</li>\n            <li>DELETE: xóa.</li>\n            <li>HEAD: kiểm tra.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Status Code</h3>\n          <ul>\n            <li>2xx: thành công (200).</li>\n            <li>3xx: chuyển hướng (301).</li>\n            <li>4xx: lỗi client (404).</li>\n            <li>5xx: lỗi server (500).</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Request gồm</h3>\n          <ul>\n            <li>Method + URL.</li>\n            <li>Header.</li>\n            <li>Body (nếu có).</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: website thương mại điện tử</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>🛍️ Người dùng nhập email, mật khẩu, thẻ ngân hàng.</p>\n          <p>🔓 Nếu dùng HTTP: dữ liệu có thể bị nghe lén.</p>\n          <p>🔒 HTTPS mã hóa dữ liệu và bảo vệ người dùng.</p>\n          <p>✅ Vì vậy mọi website đăng nhập bắt buộc HTTPS.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>HTTPS không chỉ là lựa chọn, mà là tiêu chuẩn bắt buộc cho web an toàn.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Thực hành nhanh trên trình duyệt:</p>\n      <ol>\n        <li>Truy cập một website bất kỳ.</li>\n        <li>Kiểm tra HTTP hay HTTPS.</li>\n        <li>Xem certificate được cấp bởi ai.</li>\n        <li>Nêu điều gì xảy ra khi certificate hết hạn.</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Trả lời ngắn gọn 5-7 dòng, tập trung vào bảo mật và trải nghiệm người dùng.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "23": {
    "title": "Bài 23: Email Protocols: SMTP, POP3, IMAP",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 23</p>\n        <h1>Email Protocols: SMTP, POP3, IMAP</h1>\n        <p>\n          Email hoạt động nhờ ba giao thức chính: SMTP để gửi, POP3/IMAP để nhận. Bài học này giúp bạn hiểu quy trình\n          gửi - nhận email và vì sao IMAP là lựa chọn phổ biến hiện nay.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>5 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>TCP-based</strong>\n            Giao thức tin cậy\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu email hoạt động như thế nào.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Phân biệt vai trò của SMTP, POP3, IMAP.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Nắm quy trình gửi và nhận email.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>So sánh POP3 và IMAP trong thực tế.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Áp dụng đúng giao thức trong doanh nghiệp.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Vì sao một email có thể xuất hiện trên nhiều thiết bị khác nhau mà không bị mất?\"\n        </blockquote>\n        <p>Câu trả lời nằm ở SMTP, POP3 và IMAP.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Hệ thống email gồm gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📬 Mail Client</span>\n          <p>Gmail, Outlook, Thunderbird... nơi bạn soạn và đọc email.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🏢 Mail Server</span>\n          <p>Máy chủ lưu trữ và chuyển tiếp email giữa các domain.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🔧 Protocols</span>\n          <p>SMTP để gửi, POP3/IMAP để nhận và đồng bộ.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Quy trình gửi & nhận email</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>SMTP (Gửi)</strong>\n          Client gửi email đến server, server chuyển tiếp đến server người nhận.\n        </div>\n        <div class=\"step\">\n          <strong>POP3 (Nhận)</strong>\n          Tải email về máy và thường xóa trên server.\n        </div>\n        <div class=\"step\">\n          <strong>IMAP (Nhận)</strong>\n          Đồng bộ email, dữ liệu luôn nằm trên server.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">So sánh</p>\n      <h2>POP3 và IMAP</h2>\n      <div class=\"timeline\">\n        <article class=\"timeline-card\">\n          <h3>POP3</h3>\n          <ul>\n            <li>Lưu email ở máy người dùng.</li>\n            <li>Ít đồng bộ giữa thiết bị.</li>\n            <li>Phù hợp một thiết bị duy nhất.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>IMAP</h3>\n          <ul>\n            <li>Email nằm trên server.</li>\n            <li>Đồng bộ tốt nhiều thiết bị.</li>\n            <li>Chuẩn hiện đại phổ biến.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Kỹ thuật</p>\n      <h2>Cổng kết nối phổ biến</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>SMTP</h3>\n          <ul>\n            <li>25: không mã hóa.</li>\n            <li>587: TLS.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>POP3</h3>\n          <ul>\n            <li>110: không mã hóa.</li>\n            <li>995: SSL.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>IMAP</h3>\n          <ul>\n            <li>143: không mã hóa.</li>\n            <li>993: SSL.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: email doanh nghiệp</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>📱 Nhân viên dùng điện thoại, laptop, webmail.</p>\n          <p>🔁 Cần đồng bộ email và không mất dữ liệu.</p>\n          <p>✅ SMTP để gửi, IMAP để nhận và đồng bộ.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>IMAP là lựa chọn phù hợp cho môi trường đa thiết bị.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Kiểm tra cấu hình email của bạn:</p>\n      <ol>\n        <li>Mail client đang dùng POP3 hay IMAP?</li>\n        <li>SMTP dùng port nào?</li>\n        <li>Vì sao nhà cung cấp khuyên dùng IMAP?</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Trả lời 5-7 dòng, liên hệ với nhu cầu đồng bộ nhiều thiết bị.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "24": {
    "title": "Bài 24: Truyền tải file với FTP và SFTP",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 24</p>\n        <h1>Truyền tải file với FTP và SFTP</h1>\n        <p>\n          Khi cần upload website, tải log hay chuyển file cấu hình, bạn sẽ gặp FTP hoặc SFTP. Bài học này giúp bạn\n          hiểu sự khác nhau giữa hai giao thức và chọn đúng trong thực tế.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>5 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>Port 21/22</strong>\n            FTP/SFTP\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu FTP và SFTP là gì.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Phân biệt rõ FTP và SFTP.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Nắm cách truyền file giữa client và server.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Biết khi nào không nên dùng FTP.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Áp dụng đúng giao thức trong doanh nghiệp.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Làm sao truyền file nhanh và an toàn giữa hai máy trên Internet?\"\n        </blockquote>\n        <p>Câu trả lời nằm ở FTP và SFTP.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>FTP và SFTP</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 FTP</span>\n          <p>Giao thức truyền file cổ điển, chạy trên TCP, không mã hóa dữ liệu.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🔒 SFTP</span>\n          <p>Truyền file an toàn qua SSH, mọi dữ liệu được mã hóa hoàn toàn.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">⚠️ Lưu ý</span>\n          <ul>\n            <li>SFTP khác FTPS (SFTP dùng SSH).</li>\n            <li>FTP kém an toàn, dễ bị sniffing.</li>\n            <li>SFTP là tiêu chuẩn hiện đại.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Cách FTP và SFTP hoạt động</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>FTP</strong>\n          Dùng 2 kết nối: control (port 21) và data (20/random).\n        </div>\n        <div class=\"step\">\n          <strong>Active vs Passive</strong>\n          Passive phổ biến hơn vì phù hợp firewall/NAT.\n        </div>\n        <div class=\"step\">\n          <strong>SFTP</strong>\n          Dùng 1 kết nối duy nhất qua SSH port 22.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">So sánh</p>\n      <h2>FTP vs SFTP</h2>\n      <div class=\"timeline\">\n        <article class=\"timeline-card\">\n          <h3>FTP</h3>\n          <ul>\n            <li>Không mã hóa.</li>\n            <li>Phức tạp với firewall.</li>\n            <li>Nhiều kết nối.</li>\n            <li>Ít dùng trên Internet công cộng.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>SFTP</h3>\n          <ul>\n            <li>Mã hóa toàn bộ dữ liệu.</li>\n            <li>Dễ cấu hình firewall.</li>\n            <li>Chỉ 1 kết nối.</li>\n            <li>Phổ biến trong thực tế.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Kỹ thuật</p>\n      <h2>Cổng kết nối cần nhớ</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>FTP</h3>\n          <ul>\n            <li>Control: port 21.</li>\n            <li>Data: port 20 hoặc random.</li>\n            <li>Không mã hóa.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>SFTP</h3>\n          <ul>\n            <li>Port 22.</li>\n            <li>Mã hóa qua SSH.</li>\n            <li>An toàn khi truyền file nhạy cảm.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Khi nào dùng?</h3>\n          <ul>\n            <li>Internet công cộng: ưu tiên SFTP.</li>\n            <li>Nội bộ legacy: có thể dùng FTP.</li>\n            <li>Luôn tránh gửi password qua FTP.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: quản trị web server</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>🧑‍💻 Admin cần upload source code và tải log.</p>\n          <p>🌐 Truy cập từ Internet, dữ liệu nhạy cảm.</p>\n          <p>✅ Giải pháp: dùng SFTP và xác thực bằng SSH key.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>FTP dễ bị lộ thông tin, SFTP là lựa chọn an toàn.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Trả lời ngắn gọn 1-2 dòng cho mỗi câu:</p>\n      <ol>\n        <li>Vì sao FTP không an toàn?</li>\n        <li>SFTP dùng giao thức nền nào?</li>\n        <li>Khi firewall chặn FTP, giải pháp tốt nhất là gì?</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Nhấn mạnh yếu tố bảo mật và số lượng kết nối.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "25": {
    "title": "Bài 25: Cấu hình động với DHCP",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 25</p>\n        <h1>Cấu hình động với DHCP</h1>\n        <p>\n          DHCP là lý do bạn cắm mạng là có Internet ngay. Bài học này giúp bạn hiểu quy trình cấp IP tự động và cách\n          quản lý địa chỉ trong mạng LAN.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>20 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>5 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>UDP 67/68</strong>\n            DHCP\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu DHCP là gì và vai trò trong mạng LAN.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Biết vì sao cần DHCP thay vì gán IP thủ công.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Mô tả quy trình cấp phát IP tự động.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Nhận biết thông tin DHCP cung cấp.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Phân biệt DHCP động và DHCP reservation.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Ai cấp IP, gateway, DNS cho thiết bị chỉ trong vài giây khi bạn kết nối Wi-Fi?\"\n        </blockquote>\n        <p>Câu trả lời là DHCP.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>DHCP là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p><strong>DHCP</strong> tự động cấp phát cấu hình mạng cho thiết bị.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧭 Vận hành</span>\n          <ul>\n            <li>Hoạt động tại Application Layer.</li>\n            <li>Sử dụng UDP port 67/68.</li>\n            <li>Thường nằm trên router hoặc server.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✅ DHCP cấp</span>\n          <ul>\n            <li>IP Address, Subnet Mask.</li>\n            <li>Default Gateway.</li>\n            <li>DNS Server.</li>\n            <li>Lease Time.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Quy trình DORA</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>Discover</strong>\n          Client broadcast tìm DHCP Server.\n        </div>\n        <div class=\"step\">\n          <strong>Offer</strong>\n          DHCP Server đề xuất IP.\n        </div>\n        <div class=\"step\">\n          <strong>Request</strong>\n          Client yêu cầu IP được đề xuất.\n        </div>\n        <div class=\"step\">\n          <strong>ACK</strong>\n          Server xác nhận và cấp IP.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Cấu hình</p>\n      <h2>Lease time và kiểu cấp phát</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>Lease Time</h3>\n          <ul>\n            <li>IP không vĩnh viễn.</li>\n            <li>Gần hết hạn sẽ tự gia hạn.</li>\n            <li>Hết hạn sẽ thu hồi IP.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Kiểu cấp phát</h3>\n          <ul>\n            <li>Dynamic: IP thay đổi theo thời gian.</li>\n            <li>Automatic: IP cố định sau lần đầu.</li>\n            <li>Reservation: IP cố định theo MAC.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Reservation</h3>\n          <ul>\n            <li>Dùng cho máy in, server, camera.</li>\n            <li>Quản lý dễ, IP không đổi.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: mạng văn phòng nhỏ</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>🏢 1 router, 20 máy tính, 2 máy in.</p>\n          <p>🔁 Máy tính dùng DHCP động.</p>\n          <p>🖨️ Máy in dùng DHCP reservation.</p>\n          <p>✅ Quản lý dễ, không trùng IP.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>DHCP giúp mở rộng mạng nhanh và quản lý hiệu quả.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Thực hành trên máy tính của bạn:</p>\n      <ol>\n        <li>Kiểm tra cấu hình IP hiện tại.</li>\n        <li>Xác định IP có phải DHCP cấp không.</li>\n        <li>Tìm lease time còn bao lâu.</li>\n        <li>Trả lời: nếu tắt DHCP server thì điều gì xảy ra?</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Windows: <code>ipconfig /all</code> - macOS/Linux: <code>ip a</code> hoặc <code>nmcli</code>.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "26": {
    "title": "Bài 26: SSH - Secure Shell",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 26</p>\n        <h1>SSH - Secure Shell</h1>\n        <p>\n          SSH cho phép quản trị server từ xa an toàn, mã hóa toàn bộ dữ liệu truyền. Bài học này giúp bạn hiểu SSH hoạt\n          động ra sao và cách xác thực bằng password hay SSH key.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>5 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>TCP 22</strong>\n            SSH\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu SSH là gì và vai trò trong quản trị hệ thống.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Biết vì sao SSH an toàn hơn Telnet.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Nắm cách SSH thiết lập kết nối bảo mật.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Phân biệt SSH password và SSH key.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Ứng dụng SSH trong quản trị server thực tế.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Làm sao điều khiển server từ xa mà vẫn an toàn, không lộ mật khẩu qua Internet?\"\n        </blockquote>\n        <p>Câu trả lời là SSH.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>SSH là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p><strong>SSH</strong> là giao thức truy cập và quản trị thiết bị từ xa một cách an toàn.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧭 Đặc điểm</span>\n          <ul>\n            <li>Hoạt động ở Application Layer.</li>\n            <li>Dùng TCP port 22.</li>\n            <li>Mã hóa toàn bộ dữ liệu truyền.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✅ SSH dùng để</span>\n          <ul>\n            <li>Đăng nhập server từ xa.</li>\n            <li>Thực thi lệnh quản trị.</li>\n            <li>Truyền file qua SCP/SFTP.</li>\n            <li>Tunneling/port forwarding.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Quy trình kết nối SSH</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. Kết nối</strong>\n          Client gửi yêu cầu đến server.\n        </div>\n        <div class=\"step\">\n          <strong>2. Xác thực</strong>\n          Server gửi public key, client xác thực.\n        </div>\n        <div class=\"step\">\n          <strong>3. Mã hóa</strong>\n          Hai bên tạo khóa phiên và trao đổi dữ liệu đã mã hóa.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Xác thực</p>\n      <h2>Password vs SSH Key</h2>\n      <div class=\"timeline\">\n        <article class=\"timeline-card\">\n          <h3>Password</h3>\n          <ul>\n            <li>Dễ dùng, dễ triển khai.</li>\n            <li>Kém an toàn hơn.</li>\n            <li>Dễ bị brute force nếu quản lý kém.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>SSH Key</h3>\n          <ul>\n            <li>Không gửi mật khẩu qua mạng.</li>\n            <li>An toàn, chuyên nghiệp.</li>\n            <li>Chuẩn doanh nghiệp hiện đại.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Kỹ thuật</p>\n      <h2>Thông số cần nhớ</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>SSH Key</h3>\n          <ul>\n            <li>Public Key: đặt trên server.</li>\n            <li>Private Key: giữ bí mật ở client.</li>\n            <li>Không bao giờ chia sẻ private key.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>SSH vs Telnet</h3>\n          <ul>\n            <li>SSH mã hóa, Telnet không.</li>\n            <li>SSH bảo mật cao, Telnet lỗi thời.</li>\n            <li>SSH port 22, Telnet port 23.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Công cụ phổ biến</h3>\n          <ul>\n            <li>Linux/macOS: <code>ssh</code>.</li>\n            <li>Windows: OpenSSH, PuTTY.</li>\n            <li>GUI: MobaXterm, SecureCRT.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: quản trị web server</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>☁️ Server đặt ở cloud, admin làm việc từ xa.</p>\n          <p>🔑 Đăng nhập bằng SSH key, tắt password login.</p>\n          <p>✅ Quản trị an toàn và linh hoạt.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>SSH là công cụ bắt buộc cho quản trị server hiện đại.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Trả lời ngắn gọn 1-2 dòng cho mỗi câu:</p>\n      <ol>\n        <li>Vì sao Telnet không an toàn?</li>\n        <li>SSH dùng port nào?</li>\n        <li>Vì sao SSH key an toàn hơn mật khẩu?</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Nhấn mạnh yếu tố mã hóa và cơ chế xác thực.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "27": {
    "title": "Bài 27: Mạng không dây (Wi-Fi) và các chuẩn 802.11",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 27</p>\n        <h1>Mạng không dây (Wi-Fi) và các chuẩn 802.11</h1>\n        <p>\n          Wi-Fi không chỉ là \"có sóng\". Bài học này giải thích chuẩn 802.11, khác biệt giữa 2.4 GHz và 5 GHz, cùng\n          các yếu tố ảnh hưởng tốc độ và chất lượng mạng không dây.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>5 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>802.11</strong>\n            Chuẩn Wi-Fi\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu Wi-Fi là gì và cách Wi-Fi hoạt động.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Nhận biết các chuẩn Wi-Fi (802.11 a/b/g/n/ac/ax).</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Phân biệt băng tần 2.4 GHz và 5 GHz.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Biết các yếu tố ảnh hưởng tốc độ Wi-Fi.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Ứng dụng Wi-Fi đúng cách cho nhà ở và doanh nghiệp.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Wi-Fi mạnh hay yếu phụ thuộc chuẩn, băng tần và môi trường như thế nào?\"\n        </blockquote>\n        <p>Câu trả lời nằm ở công nghệ Wi-Fi và các chuẩn 802.11.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Wi-Fi và Access Point</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Wi-Fi</span>\n          <p>Chuẩn mạng không dây dựa trên IEEE 802.11, kết nối thiết bị với LAN/Internet.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">📡 Access Point</span>\n          <p>Thiết bị phát sóng Wi-Fi, kết nối mạng không dây với mạng có dây.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✅ Lưu ý</span>\n          <ul>\n            <li>Wi-Fi hoạt động ở Layer 1 và Layer 2.</li>\n            <li>Router gia đình = Router + AP + Switch + DHCP.</li>\n            <li>Wi-Fi vẫn dùng TCP/IP như mạng dây.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Quy trình kết nối Wi-Fi</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. Quét SSID</strong>\n          Client dò sóng và chọn mạng Wi-Fi.\n        </div>\n        <div class=\"step\">\n          <strong>2. Xác thực</strong>\n          Nhập mật khẩu hoặc cơ chế bảo mật.\n        </div>\n        <div class=\"step\">\n          <strong>3. Nhận IP</strong>\n          Thiết bị nhận IP qua DHCP và truy cập mạng.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Chuẩn Wi-Fi</p>\n      <h2>802.11 a/b/g/n/ac/ax</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>Chuẩn phổ biến</h3>\n          <ul>\n            <li>802.11b/g: 2.4 GHz, tốc độ thấp.</li>\n            <li>802.11n: 2.4/5 GHz, phổ thông.</li>\n            <li>802.11ac: 5 GHz, tốc độ cao.</li>\n            <li>802.11ax: Wi-Fi 6, hiệu năng cao.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Băng tần 2.4 GHz</h3>\n          <ul>\n            <li>Tầm xa tốt, xuyên tường tốt.</li>\n            <li>Nhiều nhiễu hơn.</li>\n            <li>Tốc độ thấp hơn.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Băng tần 5 GHz</h3>\n          <ul>\n            <li>Tốc độ cao, ít nhiễu.</li>\n            <li>Tầm xa kém hơn.</li>\n            <li>Phù hợp căn hộ, văn phòng.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Tối ưu</p>\n      <h2>Yếu tố ảnh hưởng chất lượng Wi-Fi</h2>\n      <div class=\"timeline\">\n        <article class=\"timeline-card\">\n          <h3>Môi trường</h3>\n          <ul>\n            <li>Tường bê tông, kim loại.</li>\n            <li>Nhiễu từ Wi-Fi khác, Bluetooth.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>Thiết bị</h3>\n          <ul>\n            <li>Chuẩn Wi-Fi hỗ trợ.</li>\n            <li>Vị trí đặt router/AP.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: mạng Wi-Fi văn phòng nhỏ</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>🏢 30 nhân viên, nhiều laptop và điện thoại.</p>\n          <p>📶 Dùng AP Wi-Fi 5/6 và chia băng tần hợp lý.</p>\n          <p>✅ Đặt AP đúng vị trí giúp Wi-Fi ổn định.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>Wi-Fi mạnh phụ thuộc thiết kế và chuẩn mạng, không chỉ do gói Internet.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Kiểm tra Wi-Fi bạn đang dùng:</p>\n      <ol>\n        <li>Chuẩn Wi-Fi là gì? (n/ac/ax?)</li>\n        <li>Đang dùng băng tần nào?</li>\n        <li>Vì sao ở một số vị trí Wi-Fi yếu?</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Trả lời ngắn gọn 5-7 dòng, liên hệ với băng tần và môi trường.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "28": {
    "title": "Bài 28: Bảo mật mạng cơ bản: Firewall và IDS/IPS",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 28</p>\n        <h1>Bảo mật mạng cơ bản: Firewall và IDS/IPS</h1>\n        <p>\n          Firewall và IDS/IPS là tuyến phòng thủ quan trọng giúp chặn truy cập trái phép và phát hiện tấn công. Bài học\n          này giúp bạn hiểu cách các lớp bảo mật phối hợp để bảo vệ mạng.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>5 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>Defense in Depth</strong>\n            Phòng thủ nhiều lớp\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu vì sao bảo mật mạng là bắt buộc.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Giải thích Firewall là gì và cách hoạt động.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Phân biệt IDS và IPS.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Nhận biết vai trò của Firewall và IDS/IPS trong mạng.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Hiểu tư duy phòng thủ nhiều lớp.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Làm sao chặn truy cập trái phép và phát hiện tấn công đang diễn ra?\"\n        </blockquote>\n        <p>Câu trả lời nằm ở Firewall và IDS/IPS.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Firewall, IDS và IPS</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">🛡️ Firewall</span>\n          <p>Hệ thống kiểm soát và lọc lưu lượng mạng dựa trên quy tắc bảo mật.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🔍 IDS</span>\n          <p>Hệ thống phát hiện xâm nhập, giám sát và gửi cảnh báo.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🚫 IPS</span>\n          <p>Hệ thống ngăn chặn xâm nhập, phát hiện và chặn ngay tấn công.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Firewall hoạt động thế nào?</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>Kiểm tra</strong>\n          IP nguồn/đích, port, protocol, trạng thái kết nối.\n        </div>\n        <div class=\"step\">\n          <strong>Áp quy tắc</strong>\n          Allow hoặc deny/drop lưu lượng.\n        </div>\n        <div class=\"step\">\n          <strong>Ghi log</strong>\n          Theo dõi hoạt động và điều chỉnh chính sách.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">So sánh</p>\n      <h2>Firewall vs IDS vs IPS</h2>\n      <div class=\"timeline\">\n        <article class=\"timeline-card\">\n          <h3>Firewall</h3>\n          <ul>\n            <li>Chặn traffic dựa trên quy tắc.</li>\n            <li>Phát hiện tấn công ở mức cơ bản.</li>\n            <li>Là tuyến phòng thủ đầu tiên.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>IDS</h3>\n          <ul>\n            <li>Giám sát và phát hiện bất thường.</li>\n            <li>Chỉ cảnh báo, không chặn.</li>\n            <li>Hoạt động ở chế độ quan sát.</li>\n          </ul>\n        </article>\n        <article class=\"timeline-card\">\n          <h3>IPS</h3>\n          <ul>\n            <li>Phát hiện và chặn ngay.</li>\n            <li>Hoạt động inline với lưu lượng.</li>\n            <li>Phản ứng tức thì với tấn công.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Kỹ thuật</p>\n      <h2>Các loại Firewall & cách phát hiện</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>Loại Firewall</h3>\n          <ul>\n            <li>Packet Filtering.</li>\n            <li>Stateful Firewall.</li>\n            <li>Application Firewall.</li>\n            <li>NGFW (tích hợp IDS/IPS).</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Kiểu phát hiện</h3>\n          <ul>\n            <li>Signature-based: dựa mẫu tấn công.</li>\n            <li>Anomaly-based: dựa hành vi bất thường.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Defense in Depth</h3>\n          <ul>\n            <li>Kết hợp nhiều lớp bảo vệ.</li>\n            <li>Giảm rủi ro khi một lớp bị vượt qua.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: mạng doanh nghiệp nhỏ</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>🏢 Có web server, mail server và nhân viên truy cập Internet.</p>\n          <p>🛡️ Firewall chỉ mở các port cần thiết.</p>\n          <p>🔍 IDS phát hiện scan, brute force; IPS chặn IP tấn công.</p>\n          <p>✅ Hệ thống an toàn hơn và có cảnh báo rõ ràng.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>Bảo mật hiệu quả cần firewall + IDS/IPS kết hợp.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Trả lời ngắn gọn 2-3 dòng cho mỗi câu:</p>\n      <ol>\n        <li>Vì sao firewall chưa đủ để bảo mật hoàn toàn?</li>\n        <li>Khi nào nên dùng IDS, khi nào cần IPS?</li>\n        <li>Gia đình bạn đang dùng firewall nào?</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Liên hệ đến vai trò giám sát và phản ứng tức thì.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "29": {
    "title": "Bài 29: VPN - Mạng riêng ảo và bảo mật dữ liệu từ xa",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 29</p>\n        <h1>VPN - Mạng riêng ảo và bảo mật dữ liệu từ xa</h1>\n        <p>\n          VPN tạo đường hầm bảo mật để truyền dữ liệu an toàn qua Internet công cộng. Bài học này giúp bạn hiểu cách VPN\n          hoạt động, các giao thức phổ biến và tình huống ứng dụng.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>4 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>Tunnel + Encryption</strong>\n            Bảo mật dữ liệu\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu VPN là gì và vì sao cần VPN.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Giải thích cách VPN bảo vệ dữ liệu.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Nhận biết các thông số kỹ thuật quan trọng.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Áp dụng VPN vào các tình huống thực tế.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Làm sao truyền dữ liệu an toàn khi dùng Wi-Fi công cộng?\"\n        </blockquote>\n        <p>VPN giúp tạo đường hầm mã hóa để bảo vệ dữ liệu.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>VPN là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p><strong>VPN</strong> tạo đường hầm bảo mật để truyền dữ liệu an toàn qua Internet công cộng.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🔐 Bản chất</span>\n          <ul>\n            <li>Mã hóa dữ liệu.</li>\n            <li>Che giấu lưu lượng truyền tải.</li>\n            <li>Tạo kết nối riêng tư.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✅ Ứng dụng</span>\n          <ul>\n            <li>Làm việc từ xa.</li>\n            <li>Truy cập tài nguyên nội bộ.</li>\n            <li>Bảo mật khi dùng mạng công cộng.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Cách VPN hoạt động</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. Kết nối VPN</strong>\n          Thiết bị khởi tạo kết nối đến máy chủ VPN.\n        </div>\n        <div class=\"step\">\n          <strong>2. Mã hóa</strong>\n          Dữ liệu được mã hóa trước khi đi qua Internet.\n        </div>\n        <div class=\"step\">\n          <strong>3. Đường hầm</strong>\n          Lưu lượng đi trong tunnel an toàn và được giải mã ở phía server.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Kỹ thuật</p>\n      <h2>Thông số VPN cần nhớ</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>Giao thức</h3>\n          <ul>\n            <li>OpenVPN, IPSec, WireGuard.</li>\n            <li>L2TP (legacy).</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Mã hóa</h3>\n          <ul>\n            <li>AES-128, AES-256.</li>\n            <li>Phụ thuộc thuật toán trao đổi khóa.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Kiểu tunnel</h3>\n          <ul>\n            <li>Full Tunnel.</li>\n            <li>Split Tunnel.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: truy cập hệ thống kỹ thuật từ xa</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>🏭 Kỹ sư truy cập PLC, hệ thống giám sát từ xa.</p>\n          <p>🔐 Dùng Remote Access VPN, OpenVPN + AES-256.</p>\n          <p>✅ Truy cập an toàn, tránh nghe lén trên mạng công cộng.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>VPN là lớp bảo mật bắt buộc cho làm việc từ xa.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Thực hành ngắn trên máy tính của bạn:</p>\n      <ol>\n        <li>Cài một VPN client (OpenVPN hoặc WireGuard).</li>\n        <li>Kết nối đến một server test.</li>\n        <li>Kiểm tra IP trước và sau khi kết nối.</li>\n        <li>Ghi lại giao thức và chuẩn mã hóa dùng.</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Trình bày ngắn gọn 5-7 dòng, tập trung vào bảo mật và hiệu năng.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "30": {
    "title": "Bài 30: Công nghệ Điện toán đám mây (Cloud Computing)",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <p class=\"section-heading\" style=\"color: rgba(255,255,255,0.7); letter-spacing: 0.4em;\">Bài học 30</p>\n        <h1>Công nghệ Điện toán đám mây (Cloud Computing)</h1>\n        <p>\n          Cloud Computing giúp doanh nghiệp sử dụng tài nguyên CNTT linh hoạt, tiết kiệm chi phí và mở rộng nhanh. Bài\n          học này giải thích mô hình cloud và cách ứng dụng trong thực tế.\n        </p>\n        <div class=\"hero-actions\">\n          <a href=\"#objectives\" class=\"primary\">Bắt đầu học</a>\n          <a href=\"#practice\" class=\"secondary\">Làm bài tập</a>\n        </div>\n        <div class=\"stat-grid\">\n          <div class=\"stat\">\n            <strong>25 phút</strong>\n            Thời lượng gợi ý\n          </div>\n          <div class=\"stat\">\n            <strong>6 phần</strong>\n            Chủ đề trọng tâm\n          </div>\n          <div class=\"stat\">\n            <strong>IaaS / PaaS / SaaS</strong>\n            Mô hình dịch vụ\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <p class=\"section-heading\">Mục tiêu</p>\n      <h2>Kết quả học tập mong đợi</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 01</span>\n          <p>Hiểu khái niệm Cloud Computing.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 02</span>\n          <p>Phân biệt cloud với on-premise.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 03</span>\n          <p>Nhận biết mô hình dịch vụ cloud phổ biến.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 04</span>\n          <p>Nắm nguyên lý hoạt động và thông số cơ bản.</p>\n        </div>\n        <div class=\"goal\">\n          <span>🎯 Mục tiêu 05</span>\n          <p>Ứng dụng cloud trong lưu trữ và vận hành.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Đặt vấn đề:</strong>\n        <blockquote>\n          \"Có cách nào dùng tài nguyên CNTT linh hoạt mà không cần đầu tư máy chủ ban đầu?\"\n        </blockquote>\n        <p>Cloud Computing là câu trả lời.</p>\n      </div>\n    </section>\n\n    <section id=\"overview\">\n      <p class=\"section-heading\">Khái niệm</p>\n      <h2>Cloud Computing là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">📖 Định nghĩa</span>\n          <p>Cloud cung cấp tài nguyên CNTT (máy chủ, lưu trữ, phần mềm...) qua Internet theo nhu cầu.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">🧭 Đặc điểm</span>\n          <ul>\n            <li>On-demand, pay-as-you-go.</li>\n            <li>Truy cập mọi lúc, mọi nơi.</li>\n            <li>Mở rộng linh hoạt.</li>\n          </ul>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">✅ Lợi ích</span>\n          <ul>\n            <li>Giảm chi phí đầu tư ban đầu.</li>\n            <li>Triển khai nhanh.</li>\n            <li>Dễ quản lý và bảo trì.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Nguyên lý</p>\n      <h2>Cloud hoạt động như thế nào?</h2>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <strong>1. Data Center</strong>\n          Nhà cung cấp vận hành trung tâm dữ liệu lớn.\n        </div>\n        <div class=\"step\">\n          <strong>2. Ảo hóa</strong>\n          Tài nguyên được ảo hóa để chia sẻ linh hoạt.\n        </div>\n        <div class=\"step\">\n          <strong>3. Tự động</strong>\n          Phân bổ/mở rộng theo nhu cầu, trả phí theo mức dùng.\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Mô hình</p>\n      <h2>Dịch vụ & triển khai cloud</h2>\n      <div class=\"component-grid\">\n        <div class=\"component-card\">\n          <h3>Mô hình dịch vụ</h3>\n          <ul>\n            <li>IaaS: AWS EC2, Azure VM.</li>\n            <li>PaaS: Google App Engine.</li>\n            <li>SaaS: Gmail, Office 365.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Mô hình triển khai</h3>\n          <ul>\n            <li>Public Cloud: dùng chung, chi phí thấp.</li>\n            <li>Private Cloud: riêng cho doanh nghiệp.</li>\n            <li>Hybrid/Multi-Cloud: kết hợp nhiều môi trường.</li>\n          </ul>\n        </div>\n        <div class=\"component-card\">\n          <h3>Thông số kỹ thuật</h3>\n          <ul>\n            <li>CPU/vCPU, RAM, Storage.</li>\n            <li>Availability, Scalability.</li>\n            <li>Security và phân quyền.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <p class=\"section-heading\">Ví dụ</p>\n      <h2>Case study: hệ thống giám sát từ xa</h2>\n      <div class=\"case-study\">\n        <div>\n          <p>📊 Lưu dữ liệu giám sát trên cloud storage.</p>\n          <p>☁️ Dùng IaaS để chạy server, mở rộng linh hoạt.</p>\n          <p>🔐 Kết nối bảo mật qua VPN.</p>\n        </div>\n        <div class=\"callout\">\n          <strong>Kết luận:</strong>\n          <p>Cloud giúp triển khai nhanh, không cần đầu tư máy chủ vật lý.</p>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"practice\" class=\"practice\">\n      <p class=\"section-heading\">Thực hành</p>\n      <h2>Tổng kết & bài tập</h2>\n      <p>Trả lời ngắn gọn 2-3 dòng cho mỗi câu:</p>\n      <ol>\n        <li>So sánh cloud với hệ thống máy chủ on-premise.</li>\n        <li>Kể tên 1 dịch vụ IaaS, PaaS, SaaS.</li>\n        <li>Mô tả 1 kịch bản dùng cloud cho doanh nghiệp nhỏ.</li>\n      </ol>\n      <div class=\"callout\">\n        <strong>Gợi ý:</strong>\n        <p>Liên hệ đến chi phí, khả năng mở rộng và tính linh hoạt.</p>\n      </div>\n    </section>\n\n    <div class=\"footer-cta\">\n      <a href=\"../index.html\">← Về trang chủ</a>\n    </div>\n  </main>"
  },
  "31": {
    "title": "Bài 31: Xu hướng tương lai: IoT và Mạng 5G/6G",
    "main": "<main>\n    <header class=\"hero\">\n      <div class=\"hero-content\">\n        <h1>Bài 31: Xu hướng tương lai: IoT và Mạng 5G/6G</h1>\n        <p>Khám phá cách Internet of Things và mạng 5G/6G kết hợp để tạo nên hạ tầng số kết nối hàng tỷ thiết bị, mở ra thế hệ dịch vụ thời gian thực và thông minh.</p>\n        <div class=\"hero-actions\">\n          <a class=\"primary\" href=\"#objectives\">Mục tiêu bài học</a>\n          <a class=\"secondary\" href=\"#practice\">Bài tập thực hành</a>\n        </div>\n      </div>\n      <div class=\"stat-grid\">\n        <div class=\"stat\"><strong>IoT</strong>Hệ sinh thái kết nối thiết bị</div>\n        <div class=\"stat\"><strong>5G/6G</strong>Độ trễ siêu thấp, băng thông lớn</div>\n        <div class=\"stat\"><strong>Dữ liệu</strong>Nhiên liệu cho AI & tự động hóa</div>\n      </div>\n    </header>\n\n    <section id=\"objectives\">\n      <div class=\"section-heading\">Mục tiêu</div>\n      <h2>Hiểu vai trò của IoT và 5G/6G trong mạng tương lai</h2>\n      <div class=\"goal-grid\">\n        <div class=\"goal\">\n          <span>Khái niệm</span>\n          <p>Nắm được IoT, 5G/6G và các tầng kết nối tạo thành hệ sinh thái.</p>\n        </div>\n        <div class=\"goal\">\n          <span>Kỹ thuật</span>\n          <p>Biết các đặc trưng kỹ thuật: độ trễ, băng thông, slicing, edge.</p>\n        </div>\n        <div class=\"goal\">\n          <span>Ứng dụng</span>\n          <p>Liên hệ các kịch bản thông minh trong đời sống và sản xuất.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <div class=\"section-heading\">Tổng quan IoT</div>\n      <h2>Internet of Things là gì?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">Thiết bị</span>\n          <p>Cảm biến, camera, máy móc, thiết bị đeo thu thập dữ liệu liên tục.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Kết nối</span>\n          <p>Wi-Fi, NB-IoT, LPWAN, 5G đưa dữ liệu từ hiện trường lên nền tảng.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Nền tảng</span>\n          <p>Gateway, cloud, edge xử lý, lưu trữ và cung cấp API cho ứng dụng.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Ghi nhớ:</strong> IoT không chỉ là thiết bị, mà là toàn bộ chuỗi thu thập dữ liệu, truyền tải, phân tích và hành động.\n      </div>\n    </section>\n\n    <section>\n      <div class=\"section-heading\">5G/6G</div>\n      <h2>Vì sao 5G/6G là chất xúc tác cho IoT?</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">Độ trễ thấp</span>\n          <p>Cho phép điều khiển thời gian thực: xe tự hành, robot y tế, VR/AR.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Băng thông cao</span>\n          <p>Truyền video 4K/8K, dữ liệu cảm biến dày đặc và AI streaming.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Network Slicing</span>\n          <p>Tạo mạng ảo riêng cho từng dịch vụ: nhà máy, giao thông, y tế.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Edge Computing</span>\n          <p>Xử lý gần nguồn dữ liệu, giảm tải cloud và tăng tốc phản hồi.</p>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <div class=\"section-heading\">Quy trình</div>\n      <h2>Luồng dữ liệu IoT điển hình</h2>\n      <ul>\n        <li>Thiết bị cảm biến thu thập dữ liệu tại hiện trường.</li>\n        <li>Gateway hoặc edge node tiền xử lý và lọc dữ liệu quan trọng.</li>\n        <li>Mạng 5G/6G truyền dữ liệu lên nền tảng cloud hoặc trung tâm điều khiển.</li>\n        <li>AI/Analytics phân tích và đưa ra hành động (cảnh báo, tự động hóa).</li>\n        <li>Ứng dụng hiển thị dashboard, báo cáo và điều khiển thiết bị.</li>\n      </ul>\n    </section>\n\n    <section>\n      <div class=\"section-heading\">Đặc trưng</div>\n      <h2>IoT + 5G/6G tạo nên hệ thống thông minh</h2>\n      <div class=\"card-grid\">\n        <div class=\"card\">\n          <span class=\"badge\">Kết nối dày đặc</span>\n          <p>Hàng triệu thiết bị/km² hoạt động đồng thời và ổn định.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">Tự động hóa</span>\n          <p>Thiết bị tự học và phản ứng dựa trên dữ liệu thời gian thực.</p>\n        </div>\n        <div class=\"card\">\n          <span class=\"badge\">An toàn dữ liệu</span>\n          <p>Mã hóa, xác thực thiết bị, phân quyền truy cập trong toàn chuỗi.</p>\n        </div>\n      </div>\n      <div class=\"highlight-card\">\n        <strong>Tình huống:</strong> Thành phố thông minh dùng cảm biến giao thông + 5G để tối ưu đèn tín hiệu theo thời gian thực, giảm ùn tắc và tai nạn.\n      </div>\n    </section>\n\n    <section id=\"practice\">\n      <div class=\"section-heading\">Thực hành</div>\n      <h2>Bài tập củng cố</h2>\n      <ul>\n        <li>Vẽ sơ đồ 5 tầng của hệ thống IoT trong nhà máy thông minh.</li>\n        <li>So sánh 4G và 5G theo 3 tiêu chí: tốc độ, độ trễ, số lượng thiết bị.</li>\n        <li>Chọn một ứng dụng (y tế, giao thông, nông nghiệp) và mô tả vai trò của 5G.</li>\n        <li>Liệt kê rủi ro bảo mật IoT và đề xuất 3 biện pháp giảm thiểu.</li>\n      </ul>\n      <blockquote>Gợi ý: Khi thiết kế IoT, ưu tiên tính an toàn và khả năng mở rộng ngay từ đầu.</blockquote>\n    </section>\n\n    <footer>\n      <div>\n        <h2>Hoàn thành bài 31!</h2>\n        <p>Tiếp tục cập nhật kiến thức mạng thế hệ mới và chuẩn bị cho các bài học tổng kết.</p>\n      </div>\n      <div class=\"footer-actions\">\n        <a href=\"../index.html\">Quay lại trang chính</a>\n      </div>\n    </footer>\n  </main>"
  }
};
